-- Han Studio – Inhalte für den Livegang
-- Erzeugt am 2026-08-17 03:03
--
-- Reihenfolge im KAS:
--   1. schema.sql importieren  (Tabellen)
--   2. diese Datei importieren (Inhalte)
--
-- Datensatz 1 ist der Stand, mit dem gearbeitet wird.
-- Datensatz 2 ist die unberührte Kopie für „zurücksetzen“ im Adminbereich.

SET NAMES utf8mb4;

REPLACE INTO site_content (id, data) VALUES (1, '{"faq":[{"a":{"de":"Eine Vorschau mit 20 Bildern gibt es innerhalb von 48 Stunden. Die vollständige Galerie folgt nach etwa drei Wochen, der Film nach sechs Wochen.","tr":"48 saat içinde 20 karelik bir ön izleme gönderiyoruz. Tam galeri yaklaşık üç hafta, film ise altı hafta sonra hazır oluyor.","en":"A preview of 20 pictures follows within 48 hours. The full gallery comes after about three weeks, the film after six."},"q":{"de":"Wie schnell bekommen wir die Bilder?","tr":"Kareleri ne kadar sürede alıyoruz?","en":"How quickly do we get the pictures?"}},{"a":{"de":"In eurer privaten Galerie markiert ihr die Favoriten mit einem Herz und sendet die Auswahl mit einem Klick ab. Wir sehen sie sofort im Admin-Bereich – kein Excel, keine Dateinamen-Listen.","tr":"Özel galerinizde beğendiklerinizi kalp ile işaretleyip tek tıkla gönderiyorsunuz. Biz seçimi yönetim panelinde anında görüyoruz – Excel yok, dosya adı listesi yok.","en":"In your private gallery you mark favourites with a heart and send the selection with one click. We see it straight away in the admin area – no spreadsheet, no lists of file names."},"q":{"de":"Wie funktioniert die Bildauswahl fürs Album?","tr":"Albüm için fotoğraf seçimi nasıl oluyor?","en":"How does choosing pictures for the album work?"}},{"a":{"de":"Für Paare, die ein Foto- oder Filmpaket gebucht haben, ja. Alle anderen können die Einladung für 79 € einmalig erstellen.","tr":"Foto veya film paketi alan çiftler için evet. Diğerleri davetiyeyi tek seferlik 79 €\'ya oluşturabiliyor.","en":"For couples who have booked a photo or film package, yes. Everyone else can create the invitation for a one-off 79 €."},"q":{"de":"Ist die digitale Einladung wirklich kostenlos?","tr":"Dijital davetiye gerçekten ücretsiz mi?","en":"Is the digital invitation really free?"}},{"a":{"de":"Alle Galerien liegen passwortgeschützt auf Servern in der EU. Bilder werden nur mit eurer Freigabe veröffentlicht, Analytics läuft nur nach Einwilligung.","tr":"Tüm galeriler AB\'deki sunucularda parola korumalı tutuluyor. Kareler yalnızca sizin onayınızla yayınlanıyor, analiz araçları yalnızca izinle çalışıyor.","en":"All galleries sit password protected on servers in the EU. Pictures are only published with your say-so, and analytics only runs once you have agreed."},"q":{"de":"Wie sind die Daten geschützt?","tr":"Veriler nasıl korunuyor?","en":"How is the data protected?"}},{"a":{"de":"Wir sind in einem Netzwerk mit sechs Kolleginnen und Kollegen aus der Region. Im Notfall steht innerhalb von 24 Stunden ein gleichwertiger Ersatz bereit – vertraglich zugesichert.","tr":"Bölgedeki altı meslektaşımızla bir ağ içindeyiz. Acil durumda 24 saat içinde eşdeğer bir ekip devreye giriyor – sözleşmeyle güvence altında.","en":"We are part of a network of six colleagues from the region. In an emergency an equivalent replacement is ready within 24 hours – guaranteed in the contract."},"q":{"de":"Was passiert bei Krankheit?","tr":"Hastalık durumunda ne oluyor?","en":"What happens if you fall ill?"}}],"hero":{"text":{"de":"Dokumentarische Hochzeitsfotografie und Film in Krumbach und Bayerisch-Schwaben. Ruhig gearbeitet, ehrlich erzählt – und pünktlich geliefert.","tr":"Krumbach ve Bavyera-Suabya’da belgesel tarzda düğün fotoğrafçılığı ve video. Sakin çalışılmış, dürüst anlatılmış – ve zamanında teslim edilmiş.","en":"Documentary wedding photography and film in Krumbach and Bavarian Swabia. Worked quietly, told honestly – and delivered on time."},"title":{"de":"Der Tag vergeht.\\nDie Bilder bleiben.","tr":"Gün geçer.\\nKareler kalır.","en":"The day passes.\\nThe pictures stay."},"eyebrow":{"de":"Hochzeitsfotografie & Film · Krumbach","tr":"Düğün fotoğrafçılığı & film · Krumbach","en":"Wedding photography & film · Krumbach"}},"about":{"body":{"de":["Ich bin über den Journalismus zur Hochzeitsfotografie gekommen. Zehn Jahre lang habe ich für Zeitungen und Magazine fotografiert – Menschen, die nicht wussten, dass sie fotografiert werden, und Situationen, die man nicht wiederholen kann. Genau diese Haltung habe ich mitgenommen.","Eine Hochzeit ist kein Fotoshooting mit Feier drumherum. Sie ist ein Tag, an dem hunderte kleine Dinge passieren, die niemand geplant hat: der Bruder, der beim Einzug heimlich Tränen wegwischt. Die Großmutter, die zum ersten Mal seit Jahren tanzt. Die Braut, die zwei Minuten allein im Nebenzimmer steht.","Deshalb arbeite ich leise. Ich stelle keine Szenen nach, ich unterbreche keine Reden für ein besseres Foto und ich rufe niemanden zurück, weil das Licht gerade schöner ist. Was ich mache: den Tag vorher so planen, dass die schönen Momente überhaupt Platz haben.","Bei größeren Hochzeiten bin ich nicht allein. Mein Team besteht aus zwei festen Kolleginnen für Zweitkamera und Film – wir arbeiten seit vier Jahren zusammen und brauchen keine Absprachen mehr während der Feier."],"tr":["Düğün fotoğrafçılığına gazetecilikten geldim. On yıl boyunca gazeteler ve dergiler için çektim – fotoğraflandığını bilmeyen insanlar ve tekrar edilemeyecek anlar. Bu yaklaşımı olduğu gibi getirdim.","Düğün, etrafında kutlama olan bir fotoğraf çekimi değildir. Kimsenin planlamadığı yüzlerce küçük şeyin yaşandığı bir gündür: girişte gizlice gözyaşını silen abi. Yıllar sonra ilk kez dans eden anneanne. Yan odada iki dakika tek başına duran gelin.","Bu yüzden sessiz çalışıyorum. Sahne yeniden kurdurmuyorum, daha iyi bir kare için konuşmaları bölmüyorum ve ışık güzelleşti diye kimseyi geri çağırmıyorum. Yaptığım şey: günü önceden öyle planlamak ki o güzel anlara yer kalsın.","Büyük düğünlerde yalnız değilim. Ekibimde ikinci kamera ve film için iki sabit meslektaşım var – dört yıldır birlikte çalışıyoruz, düğün sırasında artık konuşmamıza bile gerek kalmıyor."],"en":["I came to wedding photography through journalism. For ten years I photographed for newspapers and magazines – people who did not know they were being photographed, and situations that cannot be repeated. That is exactly the attitude I brought with me.","A wedding is not a photo shoot with a celebration around it. It is a day on which hundreds of small things happen that nobody planned: the brother secretly wiping away tears during the entrance. The grandmother dancing for the first time in years. The bride standing alone in the side room for two minutes.","That is why I work quietly. I do not restage scenes, I do not interrupt speeches for a better picture, and I do not call anyone back because the light happens to be nicer. What I do: plan the day beforehand so that the good moments have room to happen at all.","At larger weddings I am not on my own. My team is two regular colleagues for second camera and film – we have worked together for four years and no longer need to agree anything during the celebration."]},"gear":{"de":["Zwei Vollformat-Gehäuse pro Person, jeweils mit Doppel-Kartenslot","Festbrennweiten 35 / 50 / 85 mm, f/1.4","Entfesselte Blitze für dunkle Säle","Funkmikrofone für Trauung und Reden","Doppelte Sicherung noch am Hochzeitsabend, Archiv für 24 Monate"],"tr":["Kişi başı iki full frame gövde, her biri çift kart yuvalı","35 / 50 / 85 mm f/1.4 sabit lensler","Karanlık salonlar için harici flaşlar","Nikah ve konuşmalar için telsiz mikrofonlar","Düğün akşamı çift yedekleme, 24 ay arşiv"],"en":["Two full-frame bodies per person, each with dual card slots","Prime lenses 35 / 50 / 85 mm, f/1.4","Off-camera flashes for dark halls","Radio microphones for the ceremony and speeches","Backed up twice on the wedding evening itself, archived for 24 months"]},"lead":{"de":"Fotograf und Filmemacher aus Krumbach. Seit 2016 Hochzeiten – vorher zehn Jahre Reportage.","tr":"Stuttgart\'tan fotoğrafçı ve film yapımcısı. 2016\'dan beri düğün – öncesinde on yıl foto muhabirliği.","en":"Photographer and filmmaker from Krumbach. Weddings since 2016 – ten years of reportage before that."},"name":"Ayhan Akyel","values":[{"d":{"de":"Keine Kommandos, keine Unterbrechungen. Ihr merkt uns kaum – das sieht man später auf den Bildern.","tr":"Komut yok, kesinti yok. Bizi neredeyse fark etmiyorsunuz – bu sonradan karelerde görülüyor.","en":"No commands, no interruptions. You will barely notice us – and later you can see that in the pictures."},"t":{"de":"Leise statt laut","tr":"Sessiz, gürültüsüz","en":"Quiet rather than loud"}},{"d":{"de":"Ich sage vorher, was zeitlich geht und was nicht. Lieber ein realistischer Plan als ein enttäuschter Abend.","tr":"Zaman olarak neyin mümkün olduğunu önceden söylüyorum. Hayal kırıklığı yerine gerçekçi bir plan.","en":"I say in advance what fits into the time and what does not. Better a realistic plan than a disappointed evening."},"t":{"de":"Ehrlich statt geschönt","tr":"Dürüst, süslemesiz","en":"Honest rather than polished"}},{"d":{"de":"Vorschau in 48 Stunden, Galerie in drei Wochen, Film in sechs. Vertraglich zugesichert.","tr":"48 saatte ön izleme, üç haftada galeri, altı haftada film. Sözleşmeyle garanti.","en":"Preview in 48 hours, gallery in three weeks, film in six. Guaranteed in the contract."},"t":{"de":"Pünktlich statt irgendwann","tr":"Zamanında","en":"On time rather than someday"}},{"d":{"de":"Deutsch und Türkisch – bei Familien, in denen beide Sprachen gesprochen werden, macht das den Tag deutlich entspannter.","tr":"Almanca ve Türkçe – iki dilin konuşulduğu ailelerde bu, günü ciddi şekilde rahatlatıyor.","en":"German and Turkish – in families where both languages are spoken, that makes the day considerably more relaxed."},"t":{"de":"Zweisprachig","tr":"İki dilli","en":"Bilingual"}}],"gearTitle":{"de":"Technik","tr":"Ekipman","en":"Equipment"},"valuesTitle":{"de":"Wie ich arbeite","tr":"Nasıl çalışıyorum","en":"How I work"}},"legal":{"agb":{"note":{"de":"**Hinweis:** Vorlage für die Demo-Version. Vor dem Livegang anwaltlich prüfen lassen.","en":"**Note:** A template for the demo version. Have it checked by a lawyer before going live."},"title":{"de":"Allgemeine Geschäftsbedingungen","en":"Terms and conditions"},"sections":[{"body":{"de":"Diese Bedingungen gelten für alle Foto- und Filmaufträge sowie für digitale Produkte (Online-Galerie, digitale Hochzeitseinladung) von {legalName}, {street}, {zip} {city}.","en":"These terms apply to all photography and film commissions as well as to digital products (online gallery, digital wedding invitation) of {legalName}, {street}, {zip} {city}."},"heading":{"de":"§ 1 Geltungsbereich","en":"§ 1 Scope"}},{"body":{"de":"Der Vertrag kommt mit schriftlicher Auftragsbestätigung zustande. Der Termin gilt erst mit Eingang der Anzahlung in Höhe von 30 % der Auftragssumme als reserviert. Die Restzahlung ist spätestens 14 Tage nach der Veranstaltung fällig.","en":"The contract comes into being with a written order confirmation. The date is only reserved once the deposit of 30 % of the order value has been received. The remaining payment is due no later than 14 days after the event."},"heading":{"de":"§ 2 Vertragsschluss und Reservierung","en":"§ 2 Conclusion of contract and reservation"}},{"body":{"de":"Der Umfang ergibt sich aus dem gebuchten Paket. Die Auswahl und Bearbeitung der Bilder erfolgt nach künstlerischem Ermessen der Fotografin bzw. des Fotografen. Ein Anspruch auf unbearbeitete Rohdaten besteht nicht.","en":"The scope follows from the package booked. The selection and editing of the pictures is at the photographer\'s artistic discretion. There is no entitlement to unedited raw files."},"heading":{"de":"§ 3 Leistungsumfang","en":"§ 3 Scope of services"}},{"body":{"de":"- Vorschau mit rund 20 Bildern innerhalb von 48 Stunden\\n- Vollständige Online-Galerie innerhalb von drei Wochen\\n- Hochzeitsfilm innerhalb von sechs Wochen","en":"- Preview of around 20 pictures within 48 hours\\n- Full online gallery within three weeks\\n- Wedding film within six weeks"},"heading":{"de":"§ 4 Liefer- und Bearbeitungszeiten","en":"§ 4 Delivery and editing times"}},{"body":{"de":"Die Auftraggeber erhalten ein einfaches, zeitlich und räumlich unbeschränktes Nutzungsrecht für private Zwecke einschließlich der Veröffentlichung in sozialen Netzwerken. Eine kommerzielle Nutzung oder Weitergabe an Dritte zu gewerblichen Zwecken bedarf einer gesonderten Vereinbarung. Das Urheberrecht verbleibt bei der Urheberin bzw. dem Urheber.","en":"The clients receive a simple right of use, unlimited in time and place, for private purposes including publication on social networks. Commercial use, or passing the material to third parties for commercial purposes, requires a separate agreement. Copyright remains with the author."},"heading":{"de":"§ 5 Nutzungsrechte","en":"§ 5 Rights of use"}},{"body":{"de":"Eine Veröffentlichung der Aufnahmen zu Referenzzwecken erfolgt ausschließlich nach gesonderter schriftlicher Einwilligung der abgebildeten Personen. Die Einwilligung ist freiwillig und jederzeit widerrufbar.","en":"Photographs are published for reference purposes only with the separate written consent of the people shown. That consent is voluntary and can be withdrawn at any time."},"heading":{"de":"§ 6 Veröffentlichung durch uns","en":"§ 6 Publication by us"}},{"body":{"de":"Bei Rücktritt der Auftraggeber bis 180 Tage vor dem Termin wird die Anzahlung einbehalten. Bei späterem Rücktritt werden 50 % der Auftragssumme fällig, ab 30 Tagen vor dem Termin 80 %. Bei Krankheit oder höherer Gewalt auf unserer Seite stellen wir eine gleichwertige Vertretung aus unserem Netzwerk; ist dies nicht möglich, werden bereits geleistete Zahlungen vollständig erstattet. Weitergehende Ansprüche sind ausgeschlossen.","en":"If the clients cancel up to 180 days before the date, the deposit is retained. For later cancellations 50 % of the order value falls due, and from 30 days before the date 80 %. In the event of illness or force majeure on our side we provide an equivalent replacement from our network; if that is not possible, payments already made are refunded in full. Further claims are excluded."},"heading":{"de":"§ 7 Rücktritt und Ausfall","en":"§ 7 Cancellation and non-performance"}},{"body":{"de":"Die private Galerie ist passwortgeschützt und steht für 24 Monate zur Verfügung. Die Weitergabe der Zugangsdaten an Familie und Gäste ist gestattet, eine öffentliche Verbreitung des Links nicht.","en":"The private gallery is password protected and available for 24 months. Passing the access details to family and guests is permitted; publishing the link openly is not."},"heading":{"de":"§ 8 Online-Galerie","en":"§ 8 Online gallery"}},{"body":{"de":"Die digitale Einladung ist für Kundinnen und Kunden mit gebuchtem Foto- oder Filmpaket kostenfrei. Für alle übrigen Nutzer beträgt der Preis einmalig 79 € inkl. MwSt.; die Einladungsseite bleibt zwölf Monate nach dem Hochzeitsdatum erreichbar. Für die eingegebenen Inhalte sind die erstellenden Personen verantwortlich. Es besteht kein Anspruch auf ununterbrochene Verfügbarkeit; wir bemühen uns um eine Erreichbarkeit von 99 % im Jahresmittel.","en":"The digital invitation is free of charge for clients with a booked photo or film package. For all other users the price is a one-off 79 € incl. VAT; the invitation page remains reachable for twelve months after the wedding date. The people who create an invitation are responsible for the content they enter. There is no entitlement to uninterrupted availability; we aim for 99 % availability on an annual average."},"heading":{"de":"§ 9 Digitale Hochzeitseinladung","en":"§ 9 Digital wedding invitation"}},{"body":{"de":"Verbraucher haben bei Fernabsatzverträgen ein 14-tägiges Widerrufsrecht. Bei Dienstleistungen zu einem bestimmten Termin (Veranstaltungsfotografie, § 312g Abs. 2 Nr. 9 BGB) besteht kein Widerrufsrecht. Bei digitalen Inhalten erlischt das Widerrufsrecht mit ausdrücklicher Zustimmung zum vorzeitigen Beginn der Ausführung.","en":"Consumers have a 14-day right of withdrawal for distance contracts. For services tied to a specific date (event photography, § 312g (2) no. 9 BGB) there is no right of withdrawal. For digital content the right of withdrawal lapses upon express consent to the early start of performance."},"heading":{"de":"§ 10 Widerrufsrecht","en":"§ 10 Right of withdrawal"}},{"body":{"de":"Es gilt deutsches Recht. Sollten einzelne Bestimmungen unwirksam sein, bleibt die Wirksamkeit der übrigen Bestimmungen unberührt.","en":"German law applies. Should individual provisions be invalid, the validity of the remaining provisions is unaffected."},"heading":{"de":"§ 11 Schlussbestimmungen","en":"§ 11 Final provisions"}}]},"impressum":{"note":{"de":"**Hinweis:** Dieser Text ist eine Vorlage für die Demo-Version und ersetzt keine Rechtsberatung. Vor dem Livegang sind die Angaben durch die Betreiberin bzw. den Betreiber zu prüfen und zu ergänzen.","en":"**Note:** This text is a template for the demo version and does not replace legal advice. Before going live the details must be checked and completed by the operator."},"title":{"de":"Impressum","en":"Legal notice"},"sections":[{"body":{"de":"{legalName}\\n{owner}\\n{street}\\n{zip} {city}","en":"{legalName}\\n{owner}\\n{street}\\n{zip} {city}"},"heading":{"de":"Angaben gemäß § 5 DDG","en":"Details in accordance with § 5 DDG"}},{"body":{"de":"Telefon: {phone}\\nE-Mail: {email}","en":"Phone: {phone}\\nE-mail: {email}"},"heading":{"de":"Kontakt","en":"Contact"}},{"body":{"de":"Umsatzsteuer-Identifikationsnummer gemäß § 27 a Umsatzsteuergesetz:\\nDE 123 456 789","en":"VAT identification number in accordance with § 27 a of the German VAT Act:\\nDE 123 456 789"},"heading":{"de":"Umsatzsteuer-ID","en":"VAT identification number"}},{"body":{"de":"Fotograf (Bundesrepublik Deutschland)\\nZuständige Kammer: Handwerkskammer für Schwaben, Augsburg","en":"Photographer (Federal Republic of Germany)\\nCompetent chamber: Handwerkskammer für Schwaben, Augsburg"},"heading":{"de":"Berufsbezeichnung","en":"Professional title"}},{"body":{"de":"{owner}\\n{street}, {zip} {city}","en":"{owner}\\n{street}, {zip} {city}"},"heading":{"de":"Redaktionell verantwortlich","en":"Responsible for the content"}},{"body":{"de":"Die Europäische Kommission stellt eine Plattform zur Online-Streitbeilegung (OS) bereit: [ec.europa.eu/consumers/odr](https://ec.europa.eu/consumers/odr/). Unsere E-Mail-Adresse finden Sie oben im Impressum.","en":"The European Commission provides a platform for online dispute resolution (ODR): [ec.europa.eu/consumers/odr](https://ec.europa.eu/consumers/odr/). You will find our e-mail address at the top of this legal notice."},"heading":{"de":"EU-Streitschlichtung","en":"EU dispute resolution"}},{"body":{"de":"Wir sind nicht bereit und nicht verpflichtet, an Streitbeilegungsverfahren vor einer Verbraucherschlichtungsstelle teilzunehmen.","en":"We are neither willing nor obliged to take part in dispute resolution proceedings before a consumer arbitration board."},"heading":{"de":"Verbraucherstreitbeilegung","en":"Consumer dispute resolution"}},{"body":{"de":"Alle auf dieser Website gezeigten Aufnahmen sind Platzhalter der Demo-Version. In der Live-Version stammen sämtliche Bilder von {owner} und werden ausschließlich mit schriftlicher Einwilligung der abgebildeten Personen veröffentlicht.","en":"All photographs shown on this website are placeholders of the demo version. In the live version every picture is by {owner} and is published only with the written consent of the people shown."},"heading":{"de":"Bildnachweis","en":"Picture credits"}},{"body":{"de":"Als Diensteanbieter sind wir für eigene Inhalte auf diesen Seiten nach den allgemeinen Gesetzen verantwortlich. Für Inhalte externer Links ist stets der jeweilige Anbieter verantwortlich. Zum Zeitpunkt der Verlinkung waren keine Rechtsverstöße erkennbar.","en":"As a service provider we are responsible for our own content on these pages under general law. The respective provider is always responsible for the content of external links. At the time of linking no legal infringements were apparent."},"heading":{"de":"Haftung für Inhalte und Links","en":"Liability for content and links"}}]},"datenschutz":{"note":{"de":"**Hinweis:** Dieser Text ist eine Vorlage für die Demo-Version. Vor dem Livegang ist er an die tatsächlich eingesetzten Dienste anzupassen und juristisch zu prüfen.","en":"**Note:** This text is a template for the demo version. Before going live it must be adapted to the services actually used and checked by a lawyer."},"title":{"de":"Datenschutzerklärung","en":"Privacy policy"},"sections":[{"body":{"de":"{legalName}, {owner}, {street}, {zip} {city}\\nE-Mail: {email} · Telefon: {phone}","en":"{legalName}, {owner}, {street}, {zip} {city}\\nE-mail: {email} · Phone: {phone}"},"heading":{"de":"1. Verantwortlicher","en":"1. Controller"}},{"body":{"de":"Diese Website wird bei einem Anbieter mit Serverstandort in der Europäischen Union betrieben. Beim Aufruf der Seite werden technisch notwendige Daten (IP-Adresse in gekürzter Form, Datum und Uhrzeit, aufgerufene Seite, Browsertyp) in Server-Logfiles verarbeitet. Rechtsgrundlage ist Art. 6 Abs. 1 lit. f DSGVO (berechtigtes Interesse am sicheren und stabilen Betrieb). Die Logfiles werden nach spätestens 30 Tagen gelöscht. Mit dem Hoster besteht ein Auftragsverarbeitungsvertrag nach Art. 28 DSGVO.","en":"This website is run with a provider whose servers are located in the European Union. When you open the site, technically necessary data (IP address in shortened form, date and time, page requested, browser type) is processed in server log files. The legal basis is Art. 6 (1) (f) GDPR (legitimate interest in secure and stable operation). The log files are deleted after 30 days at the latest. A data processing agreement under Art. 28 GDPR is in place with the host."},"heading":{"de":"2. Hosting und Server-Logfiles","en":"2. Hosting and server log files"}},{"body":{"de":"Alle Schriftarten werden lokal von unserem eigenen Server geladen. Es besteht dabei **keine Verbindung zu Servern von Google**. Karteninhalte (Google Maps) werden nicht automatisch eingebunden – erst wenn Sie aktiv auf einen Kartenlink klicken, verlassen Sie diese Website.","en":"All fonts are loaded locally from our own server. **No connection to Google servers** is made in the process. Map content (Google Maps) is not embedded automatically – you only leave this website once you actively click a map link."},"heading":{"de":"3. Schriften und externe Inhalte","en":"3. Fonts and external content"}},{"body":{"de":"Technisch notwendige Speicherungen (z. B. Ihre Cookie-Entscheidung, der Zugang zur privaten Galerie) erfolgen auf Grundlage von § 25 Abs. 2 TDDDG. Statistik- und Marketing-Cookies werden ausschließlich nach Ihrer ausdrücklichen Einwilligung gesetzt (Art. 6 Abs. 1 lit. a DSGVO, § 25 Abs. 1 TDDDG). Ihre Einwilligung können Sie jederzeit mit Wirkung für die Zukunft widerrufen:\\n\\n{{consent}}","en":"Technically necessary storage (e.g. your cookie decision, access to the private gallery) takes place on the basis of § 25 (2) TDDDG. Statistics and marketing cookies are only set after your express consent (Art. 6 (1) (a) GDPR, § 25 (1) TDDDG). You can withdraw your consent at any time with effect for the future:\\n\\n{{consent}}"},"heading":{"de":"4. Cookies und Einwilligung","en":"4. Cookies and consent"}},{"body":{"de":"Wenn Sie uns über das Formular, per E-Mail, Telefon oder WhatsApp kontaktieren, verarbeiten wir die von Ihnen angegebenen Daten zur Bearbeitung Ihrer Anfrage. Rechtsgrundlage ist Art. 6 Abs. 1 lit. b DSGVO (vorvertragliche Maßnahmen) bzw. lit. f DSGVO. Anfragen ohne anschließenden Vertragsschluss löschen wir nach spätestens zwölf Monaten; bei Vertragsschluss gelten die handels- und steuerrechtlichen Aufbewahrungsfristen von bis zu zehn Jahren.","en":"If you contact us through the form, by e-mail, by phone or via WhatsApp, we process the data you provide in order to handle your enquiry. The legal basis is Art. 6 (1) (b) GDPR (pre-contractual measures) or (f) GDPR. Enquiries that do not lead to a contract are deleted after twelve months at the latest; where a contract is concluded, the commercial and tax retention periods of up to ten years apply."},"heading":{"de":"5. Kontaktformular und Anfragen","en":"5. Contact form and enquiries"}},{"body":{"de":"Die Online-Galerie ist ausschließlich mit Zugangscode und Passwort erreichbar und über die Datei `robots.txt` sowie ein `noindex`-Meta-Tag von Suchmaschinen ausgeschlossen. Gespeichert werden der Zugriffszeitpunkt sowie die von Ihnen markierte Bildauswahl. Rechtsgrundlage ist Art. 6 Abs. 1 lit. b DSGVO (Vertragserfüllung). Galerien werden spätestens 24 Monate nach der Hochzeit gelöscht, sofern nichts anderes vereinbart wurde.","en":"The online gallery can only be reached with an access code and a password and is excluded from search engines through the `robots.txt` file and a `noindex` meta tag. What is stored is the time of access and the picture selection you have marked. The legal basis is Art. 6 (1) (b) GDPR (performance of a contract). Galleries are deleted 24 months after the wedding at the latest, unless agreed otherwise."},"heading":{"de":"6. Private Kundengalerie","en":"6. Private client gallery"}},{"body":{"de":"Beim Erstellen einer Einladung verarbeiten wir die von Ihnen eingegebenen Angaben (Namen, Datum, Ort, Text, optional ein Bild) zur Bereitstellung der Einladungsseite. Rückmeldungen Ihrer Gäste (Name, Zu- oder Absage, Personenzahl, optionale Nachricht) werden zur Weitergabe an Sie als Gastgeberin bzw. Gastgeber gespeichert. Verantwortlich für die Inhalte der jeweiligen Einladung sind die erstellenden Paare; wir handeln insoweit als Auftragsverarbeiter. Einladungsseiten sind nicht indexierbar und werden zwölf Monate nach dem Hochzeitsdatum gelöscht.","en":"When you create an invitation we process the details you enter (names, date, place, text, optionally a picture) in order to provide the invitation page. Replies from your guests (name, acceptance or refusal, number of people, optional message) are stored in order to pass them on to you as the host. The couples who create an invitation are responsible for its content; in that respect we act as a processor. Invitation pages cannot be indexed and are deleted twelve months after the wedding date."},"heading":{"de":"7. Digitale Hochzeitseinladung","en":"7. Digital wedding invitation"}},{"body":{"de":"Sofern Sie eingewilligt haben, nutzen wir Google Analytics 4 mit aktivierter IP-Anonymisierung. Anbieter ist Google Ireland Limited. Eine Übermittlung in Drittländer erfolgt auf Grundlage der EU-Standardvertragsklauseln und des EU-US Data Privacy Framework. Ohne Ihre Einwilligung wird kein Analytics-Skript geladen.","en":"Where you have given consent, we use Google Analytics 4 with IP anonymisation enabled. The provider is Google Ireland Limited. Any transfer to third countries takes place on the basis of the EU standard contractual clauses and the EU-US Data Privacy Framework. Without your consent no analytics script is loaded."},"heading":{"de":"8. Reichweitenmessung","en":"8. Audience measurement"}},{"body":{"de":"- Auskunft über die zu Ihnen gespeicherten Daten (Art. 15 DSGVO)\\n- Berichtigung unrichtiger Daten (Art. 16 DSGVO)\\n- Löschung (Art. 17 DSGVO) und Einschränkung der Verarbeitung (Art. 18 DSGVO)\\n- Datenübertragbarkeit (Art. 20 DSGVO)\\n- Widerspruch gegen Verarbeitungen auf Grundlage berechtigter Interessen (Art. 21 DSGVO)\\n- Widerruf erteilter Einwilligungen mit Wirkung für die Zukunft (Art. 7 Abs. 3 DSGVO)\\n- Beschwerde bei einer Aufsichtsbehörde (Art. 77 DSGVO)\\n\\nZuständige Aufsichtsbehörde: Bayerisches Landesamt für Datenschutzaufsicht (BayLDA), Promenade 18, 91522 Ansbach.","en":"- Information about the data stored about you (Art. 15 GDPR)\\n- Correction of inaccurate data (Art. 16 GDPR)\\n- Erasure (Art. 17 GDPR) and restriction of processing (Art. 18 GDPR)\\n- Data portability (Art. 20 GDPR)\\n- Objection to processing based on legitimate interests (Art. 21 GDPR)\\n- Withdrawal of consent given, with effect for the future (Art. 7 (3) GDPR)\\n- Complaint to a supervisory authority (Art. 77 GDPR)\\n\\nCompetent supervisory authority: Bayerisches Landesamt für Datenschutzaufsicht (BayLDA), Promenade 18, 91522 Ansbach."},"heading":{"de":"9. Ihre Rechte","en":"9. Your rights"}},{"body":{"de":"Aufnahmen von Hochzeiten werden ausschließlich mit gesonderter schriftlicher Einwilligung der abgebildeten Personen veröffentlicht. Diese Einwilligung ist freiwillig, unabhängig vom Fotoauftrag und jederzeit mit Wirkung für die Zukunft widerrufbar.","en":"Photographs of weddings are published only with the separate written consent of the people shown. That consent is voluntary, independent of the photography contract and can be withdrawn at any time with effect for the future."},"heading":{"de":"10. Bildrechte und Veröffentlichung","en":"10. Image rights and publication"}}]}},"posts":[{"faq":[{"a":{"de":"Für Samstage zwischen Mai und September sind zwölf bis achtzehn Monate üblich. Unter der Woche und in der Nebensaison reichen oft sechs Monate.","tr":"Mayıs–Eylül arası cumartesiler için on iki ila on sekiz ay normaldir. Hafta içi ve sezon dışında çoğu zaman altı ay yeterli oluyor.","en":"For Saturdays between May and September, twelve to eighteen months is usual. On weekdays and out of season, six months is often enough."},"q":{"de":"Wie früh sollten wir den Hochzeitsfotografen buchen?","tr":"Düğün fotoğrafçısını ne kadar önceden ayırtmalıyız?","en":"How early should we book the wedding photographer?"}},{"a":{"de":"Ab etwa 120 Gästen oder wenn sich Braut und Bräutigam getrennt vorbereiten, lohnt sich die zweite Kamera fast immer. Bei kleinen Feiern ist sie meist verzichtbar.","tr":"Yaklaşık 120 kişiden sonra ya da gelin ve damat ayrı hazırlanıyorsa ikinci kamera neredeyse her zaman işe yarıyor. Küçük kutlamalarda genelde gerekmiyor.","en":"From about 120 guests, or when the bride and groom get ready separately, the second camera is almost always worth it. At small celebrations it is usually dispensable."},"q":{"de":"Ist ein zweiter Fotograf notwendig?","tr":"İkinci bir fotoğrafçı gerekli mi?","en":"Is a second photographer necessary?"}}],"body":{"de":["Die meisten Paare buchen ihren Hochzeitsfotografen nach zwei Kriterien: Bildsprache und Preis. Beides ist wichtig, aber beides sagt wenig darüber aus, wie der Tag tatsächlich ablaufen wird. Die folgenden Fragen kosten euch ein Gespräch und ersparen euch im Zweifel eine Enttäuschung.","## 1. Wer fotografiert tatsächlich bei uns?","Bei größeren Studios ist die Person im Erstgespräch nicht immer die Person am Hochzeitstag. Lasst euch den Namen geben und fragt nach einer vollständigen Hochzeit von genau dieser Person – nicht nach einer Best-of-Auswahl aus mehreren Aufträgen.","## 2. Dürfen wir eine komplette Hochzeit sehen?","Eine Galerie mit 30 Höhepunkten kann jeder zusammenstellen. Interessant ist, wie die zweihundert Bilder dazwischen aussehen: die Rede, die niemand geplant hat, der dunkle Saal um 22 Uhr, die Familienaufstellung mit 40 Personen.","## 3. Was passiert bei Krankheit oder Ausfall?","Ein seriöser Vertrag regelt das schriftlich: Ersatz aus einem Netzwerk innerhalb einer festen Frist oder vollständige Rückerstattung. Eine mündliche Zusage ist an dieser Stelle zu wenig.","## 4. Wie lange dauert die Lieferung – und was steht im Vertrag?","„Ein paar Wochen“ ist keine Frist. Fragt nach konkreten Zahlen für Vorschau, vollständige Galerie und Film, und danach, ob diese Fristen vertraglich zugesichert sind.","## 5. Wie viele Bilder bekommen wir, und in welcher Form?","Wichtig ist weniger die Anzahl als das Format: Bekommt ihr die Bilder in voller Auflösung zum Herunterladen? Gibt es eine Online-Galerie? Dürft ihr die Bilder privat frei nutzen?","## 6. Wart ihr schon einmal in unserer Location?","Wer die Location kennt, weiß, wo um 18 Uhr noch Licht steht und welche Wege wie lange dauern. Wer sie nicht kennt, sollte vorher hinfahren – fragt, ob das eingeplant ist.","## 7. Was passiert mit unseren Bildern?","Veröffentlichung auf Website und Social Media darf nur mit gesonderter, freiwilliger Einwilligung erfolgen. Diese Einwilligung muss unabhängig vom Fotoauftrag sein und jederzeit widerrufbar bleiben.","Wenn eine Fotografin oder ein Fotograf auf alle sieben Fragen ruhig und konkret antwortet, habt ihr die wichtigste Information schon: Da arbeitet jemand, der seinen Ablauf kennt."],"tr":["Çiftlerin çoğu düğün fotoğrafçısını iki ölçüte göre seçiyor: görsel tarz ve fiyat. İkisi de önemli, ama ikisi de günün gerçekte nasıl geçeceği hakkında pek bir şey söylemiyor. Aşağıdaki sorular size bir görüşmeye mal olur, karşılığında olası bir hayal kırıklığını önler.","## 1. Bizim düğünümüzde gerçekte kim çekecek?","Büyük stüdyolarda ilk görüşmedeki kişi, düğün günü gelen kişi olmayabiliyor. İsmi net alın ve tam olarak o kişinin çektiği eksiksiz bir düğün isteyin – farklı işlerden derlenmiş bir seçki değil.","## 2. Eksiksiz bir düğün görebilir miyiz?","Otuz karelik bir seçkiyi herkes hazırlayabilir. Asıl mesele aradaki iki yüz karenin nasıl olduğu: kimsenin planlamadığı konuşma, gece 22\'de karanlık salon, kırk kişilik aile fotoğrafı.","## 3. Hastalık ya da aksilik durumunda ne oluyor?","Ciddi bir sözleşme bunu yazılı düzenler: belirli bir süre içinde ağdan eşdeğer ekip ya da tam iade. Bu konuda sözlü güvence yeterli değil.","## 4. Teslim ne kadar sürüyor – ve sözleşmede ne yazıyor?","\\"Birkaç hafta\\" bir süre değildir. Ön izleme, tam galeri ve film için somut sayılar isteyin; bu sürelerin sözleşmeyle güvence altına alınıp alınmadığını sorun.","## 5. Kaç kare alıyoruz ve hangi biçimde?","Sayıdan çok biçim önemli: Kareleri tam çözünürlükte indirebiliyor musunuz? Online galeri var mı? Kareleri özel kullanımda serbestçe kullanabiliyor musunuz?","## 6. Bizim mekânımızda daha önce çekim yaptınız mı?","Mekânı bilen kişi, saat 18\'de ışığın nerede durduğunu ve hangi geçişin ne kadar sürdüğünü bilir. Bilmeyen önceden gidip görmeli – bunun planlanıp planlanmadığını sorun.","## 7. Karelerimize ne olacak?","Web sitesinde ve sosyal medyada yayın, yalnızca ayrı ve gönüllü bir izinle yapılabilir. Bu izin fotoğraf işinden bağımsız olmalı ve her zaman geri alınabilmeli.","Bir fotoğrafçı bu yedi sorunun hepsine sakin ve somut cevap veriyorsa, en önemli bilgiyi zaten almışsınız demektir: karşınızda akışını bilen biri var."],"en":["Most couples book their wedding photographer on two criteria: visual style and price. Both matter, but neither says much about how the day will actually run. The following questions cost you one conversation and, in case of doubt, save you a disappointment.","## 1. Who will actually be photographing us?","At larger studios the person in the first conversation is not always the person on the wedding day. Ask for the name, and ask to see a complete wedding by exactly that person – not a best-of selection from several jobs.","## 2. May we see one complete wedding?","Anyone can assemble a gallery of 30 highlights. What is interesting is what the two hundred pictures in between look like: the speech nobody planned, the dark hall at 10 pm, the family line-up with 40 people in it.","## 3. What happens in case of illness or cancellation?","A serious contract settles this in writing: a replacement from a network within a fixed deadline, or a full refund. A verbal promise is not enough at this point.","## 4. How long does delivery take – and what does the contract say?","\\"A few weeks\\" is not a deadline. Ask for concrete numbers for the preview, the full gallery and the film, and then ask whether those deadlines are guaranteed in the contract.","## 5. How many pictures do we get, and in what form?","The number matters less than the format: do you get the pictures in full resolution to download? Is there an online gallery? Are you free to use the pictures privately?","## 6. Have you been to our venue before?","Someone who knows the venue knows where there is still light at 6 pm and how long each route takes. Someone who does not know it should drive out beforehand – ask whether that is planned in.","## 7. What happens to our pictures?","Publication on a website and on social media may only happen with separate, voluntary consent. That consent has to be independent of the photography contract and must remain revocable at any time.","If a photographer answers all seven questions calmly and concretely, you already have the most important information: this is somebody who knows how their day runs."]},"date":"2026-05-18","seed":"lum-blog-fragen","slug":"hochzeitsfotograf-finden-sieben-fragen","title":{"de":"Hochzeitsfotograf finden: 7 Fragen, die ihr vor der Buchung stellen solltet","tr":"Düğün fotoğrafçısı seçerken sormanız gereken 7 soru","en":"Finding a wedding photographer: 7 questions to ask before you book"},"excerpt":{"de":"Der Preis allein sagt wenig. Diese sieben Fragen zeigen euch in zehn Minuten, ob jemand zu eurem Tag passt – und decken die Punkte auf, über die später am häufigsten gestritten wird.","tr":"Fiyat tek başına bir şey söylemez. Bu yedi soru, on dakikada size uygun olup olmadığını gösterir – ve sonradan en çok tartışma çıkan noktaları önceden ortaya koyar.","en":"Price alone says little. These seven questions show you in ten minutes whether somebody suits your day – and expose the points that later cause the most arguments."},"citySlug":"stuttgart","uploads":[]},{"faq":[{"a":{"de":"30 bis 45 Minuten reichen für die Bilder, die später wirklich verwendet werden. Längere Shootings werden für die meisten Paare anstrengend, ohne dass die Ergebnisse besser werden.","tr":"Sonradan gerçekten kullanılan kareler için 30–45 dakika yeterli. Daha uzun çekimler çoğu çift için yorucu oluyor ve sonuç daha iyi olmuyor.","en":"30 to 45 minutes is enough for the pictures that actually get used later. Longer shoots become exhausting for most couples without the results getting any better."},"q":{"de":"Wie lange dauert ein Paarshooting?","tr":"Çift çekimi ne kadar sürer?","en":"How long does a couple shoot take?"}},{"a":{"de":"Vorher, direkt im Anschluss an den Sektempfang. Dann sind alle Gäste anwesend und die Aufstellung dauert halb so lang.","tr":"Önce, karşılamanın hemen ardından. O anda tüm misafirler orada olur ve dizilim yarı sürede tamamlanır.","en":"Before, straight after the drinks reception. Then all the guests are present and lining everyone up takes half as long."},"q":{"de":"Sollen die Gruppenbilder vor oder nach dem Essen sein?","tr":"Grup fotoğrafları yemekten önce mi sonra mı?","en":"Should the group pictures be before or after dinner?"}}],"body":{"de":["Fast jede Hochzeit, bei der am Ende Zeit fehlt, hat dasselbe Problem: Der Ablauf wurde nach den Wünschen der Location geplant, nicht nach dem Licht. Dabei ist die goldene Stunde der einzige Punkt im Tagesablauf, den niemand verschieben kann.","## Wann ist die goldene Stunde?","Sie beginnt etwa eine Stunde vor Sonnenuntergang und dauert je nach Jahreszeit 30 bis 50 Minuten. Im Juni in Bayerisch-Schwaben heißt das ungefähr 20:15 Uhr, Ende September bereits 18:30 Uhr. Ein Unterschied von fast zwei Stunden – geplant wird der Tag aber oft mit demselben Schema.","## Ein Ablauf, der aufgeht","Getting Ready ab drei Stunden vor der Trauung, mit Puffer für die Anfahrt. Trauung. Danach Sektempfang und Gruppenbilder, solange alle Gäste noch beisammen sind – das dauert mit 40 Personen etwa 25 Minuten, nicht zehn.","Der entscheidende Block: 30 bis 45 Minuten Paarshooting, gelegt auf die goldene Stunde. Das bedeutet, dass das Abendessen entweder davor endet oder danach beginnt. Beides funktioniert – nur mitten hinein sollte es nicht fallen.","## Die drei häufigsten Fehler","Erstens: Gruppenbilder erst nach dem Essen. Dann sind einige Gäste schon draußen, andere nicht mehr ganz bei der Sache. Zweitens: kein Puffer zwischen Trauung und Empfang – zehn Minuten Verspätung verschieben den ganzen Abend. Drittens: das Paarshooting auf die Mittagszeit legen, weil dann gerade Zeit ist. Hartes Mittagslicht ist die schwierigste Situation des Tages.","## Was tun, wenn es regnet?","Ein guter Plan hat für jeden Außenpunkt eine Innenalternative, die vorher angesehen wurde. Regen ist kein Problem, wenn er eingeplant ist – überdachte Eingänge, Fensterlicht und Schirme ergeben oft die ungewöhnlicheren Bilder."],"tr":["Sonunda zaman yetmeyen düğünlerin neredeyse hepsinde aynı sorun var: akış, mekânın istekleri üzerine kurulmuş, ışığın üzerine değil. Oysa altın saat, günün kimsenin erteleyemeyeceği tek noktası.","## Altın saat ne zaman?","Gün batımından yaklaşık bir saat önce başlar ve mevsime göre 30–50 dakika sürer. Baden-Württemberg\'de haziranda bu aşağı yukarı 20:15, eylül sonunda ise 18:30 demek. Neredeyse iki saatlik fark – ama gün çoğu zaman aynı şablonla planlanıyor.","## İşleyen bir akış","Hazırlık, nikahtan üç saat önce başlar, yol için pay bırakılır. Nikah. Ardından karşılama ve grup fotoğrafları – henüz herkes bir aradayken. Kırk kişiyle bu on değil, yaklaşık 25 dakika sürer.","Belirleyici blok: altın saate denk getirilmiş 30–45 dakikalık çift çekimi. Bu da akşam yemeğinin ya ondan önce bitmesi ya da sonra başlaması demek. İkisi de olur – yeter ki tam ortasına denk gelmesin.","## En sık yapılan üç hata","Birincisi: grup fotoğraflarını yemekten sonraya bırakmak. O saatte bir kısım misafir dışarıda, bir kısmının aklı başka yerde olur. İkincisi: nikah ile karşılama arasına pay koymamak – on dakikalık gecikme bütün akşamı kaydırır. Üçüncüsü: çift çekimini öğlene almak, çünkü \\"o saatte boşluk var\\". Sert öğle ışığı günün en zor koşuludur.","## Yağmur yağarsa?","İyi bir planda her açık hava noktasının, önceden görülmüş bir kapalı alternatifi vardır. Yağmur, planlandığı sürece sorun değildir – kapalı girişler, pencere ışığı ve şemsiyeler çoğu zaman daha sıra dışı kareler verir."],"en":["Almost every wedding that runs out of time at the end has the same problem: the running order was planned around what the venue wanted, not around the light. Yet the golden hour is the one point in the day nobody can move.","## When is the golden hour?","It begins about an hour before sunset and lasts 30 to 50 minutes depending on the season. In June in Bavarian Swabia that means roughly 8:15 pm, by the end of September it is already 6:30 pm. A difference of almost two hours – and yet the day is often planned to the same template.","## A running order that works","Getting ready from three hours before the ceremony, with slack for the journey. The ceremony. Then the drinks reception and the group pictures, while all the guests are still together – with 40 people that takes about 25 minutes, not ten.","The decisive block: 30 to 45 minutes of couple shoot, placed in the golden hour. That means dinner either ends before it or begins after it. Both work – it just should not fall right in the middle.","## The three most common mistakes","First: group pictures only after dinner. By then some guests are already outside and others are no longer quite with you. Second: no slack between the ceremony and the reception – ten minutes of delay shifts the whole evening. Third: putting the couple shoot at midday because that is when there happens to be time. Hard midday light is the most difficult situation of the day.","## What to do if it rains?","A good plan has an indoor alternative for every outdoor point, looked at in advance. Rain is not a problem if it is planned for – covered entrances, window light and umbrellas often give the more unusual pictures."]},"date":"2026-06-24","seed":"lum-blog-zeitplan","slug":"hochzeit-zeitplan-licht","title":{"de":"Der Zeitplan, der wirklich funktioniert – und warum das Licht ihn bestimmt","tr":"Gerçekten işe yarayan düğün akışı – ve neden ışık belirler","en":"The timeline that actually works – and why the light decides it"},"excerpt":{"de":"Die schönsten Paarbilder entstehen in einem Zeitfenster von 40 Minuten. Wer den Tag darum herum plant, braucht keine Bilder nachzustellen. So sieht ein realistischer Ablauf aus.","tr":"En güzel çift kareleri 40 dakikalık bir aralıkta çıkıyor. Günü onun etrafına kuran çift, hiçbir kareyi yeniden kurgulamak zorunda kalmıyor. Gerçekçi bir akış şöyle görünür.","en":"The best couple pictures happen in a window of 40 minutes. Plan the day around it and you never have to restage anything. This is what a realistic running order looks like."},"citySlug":"stuttgart"},{"faq":[{"a":{"de":"Nein. Beide Termine lassen sich in einem Paket zusammenfassen; das ist in der Regel günstiger als zwei Einzelbuchungen und sorgt dafür, dass beide Abende dieselbe Bildsprache haben.","tr":"Hayır. İki tarih tek pakette birleştirilebilir; bu genelde iki ayrı anlaşmadan daha uygun oluyor ve iki akşamın da aynı görsel dilde olmasını sağlıyor.","en":"No. Both dates can be combined in one package; that is usually cheaper than two separate bookings and makes sure both evenings have the same visual language."},"q":{"de":"Braucht man für Kına-Nacht und Hochzeit zwei getrennte Buchungen?","tr":"Kına gecesi ve düğün için iki ayrı anlaşma mı gerekiyor?","en":"Do you need two separate bookings for the kına night and the wedding?"}},{"a":{"de":"Bei 150 Gästen sind 30 bis 45 Minuten realistisch. Plant diesen Punkt fest ein, sonst verschiebt er den ganzen Abend.","tr":"150 misafirde 30–45 dakika gerçekçi. Bu maddeyi akışa sabit koyun, yoksa bütün akşamı kaydırıyor.","en":"With 150 guests, 30 to 45 minutes is realistic. Plan this point in firmly, otherwise it shifts the whole evening."},"q":{"de":"Wie lange dauert das Goldanstecken?","tr":"Takı takma ne kadar sürer?","en":"How long does the pinning of gold take?"}}],"body":{"de":["Eine deutsch-türkische Hochzeit ist selten ein Tag. Häufig sind es zwei oder drei: die Kına-Nacht, das Standesamt und die große Feier – manchmal über zwei Wochenenden verteilt, manchmal an aufeinanderfolgenden Abenden. Für die Fotografie heißt das vor allem: vorher klären, was wann stattfindet und wer welche Rolle hat.","## Die Kına-Nacht ist kein Vorprogramm","Der Henna-Abend ist emotional oft der intensivste Teil der ganzen Feier. Der Moment, in dem der Braut die Hand geschlossen wird, während die Schwiegermutter die Goldmünze hineinlegt, dauert vielleicht 40 Sekunden. Wer in dieser Zeit den Objektivwechsel macht, hat ihn verpasst.","Praktisch bedeutet das: zwei Kameras, kein Wechsel während des Rituals, und vorher wissen, aus welcher Richtung die Braut hereingeführt wird. Das Licht ist meist warm und schwach – lichtstarke Festbrennweiten sind hier keine Spielerei, sondern Voraussetzung.","## Standesamt und Nikah trennen","Viele Paare haben eine standesamtliche Trauung und zusätzlich einen Nikah. Beide brauchen Zeit im Plan, auch wenn der eine Termin nur 20 Minuten dauert. Fragt vorher, ob im Trauzimmer fotografiert werden darf und wo genau ihr stehen dürft – die Regeln unterscheiden sich von Ort zu Ort.","## Der Einzug und das Geldanstecken","Bei der großen Feier sind zwei Programmpunkte gesetzt: der Einzug des Paares und das Anstecken von Gold und Geld. Letzteres kann bei großen Familien 45 Minuten dauern und ist für die Gäste einer der wichtigsten Momente – im Zeitplan wird er trotzdem regelmäßig vergessen.","## Zweisprachigkeit ist Arbeitserleichterung","Wenn eine Großmutter nur Türkisch spricht und der Trauzeuge nur Deutsch, entscheidet die Verständigung darüber, wie entspannt die Gruppenbilder werden. Ein Team, das beide Sprachen spricht, spart bei 40 Personen leicht zehn Minuten – und die Bilder sehen entsprechend gelöster aus.","## Was in den Zeitplan gehört","Kına-Ritual, Einzug, Nikah beziehungsweise Trauung, Goldanstecken, Eröffnungstanz, Halay. Für jeden dieser Punkte eine Uhrzeit und eine grobe Dauer – mehr braucht es nicht, damit der Tag ohne Kommandos abläuft."],"tr":["Alman-Türk düğünü nadiren tek bir gündür. Çoğu zaman iki ya da üç: kına gecesi, nikah dairesi ve büyük düğün – kimi zaman iki hafta sonuna yayılır, kimi zaman ardışık akşamlarda olur. Fotoğraf açısından bunun anlamı şu: neyin ne zaman olduğu ve kimin hangi rolde olduğu önceden netleşmeli.","## Kına gecesi bir ön program değildir","Kına, duygusal olarak çoğu zaman tüm kutlamanın en yoğun bölümüdür. Kaynananın altını avuca koyup gelinin elinin kapatıldığı an belki 40 saniye sürer. O sırada lens değiştiren, o anı kaçırmıştır.","Pratikte bu şu demek: iki kamera, ritüel sırasında değişiklik yok ve gelinin hangi yönden getirileceğini önceden bilmek. Işık genelde sıcak ve zayıftır – geniş diyaframlı sabit lensler burada bir lüks değil, gereklilik.","## Nikah dairesi ile dinî nikahı ayırın","Birçok çiftin hem resmî nikahı hem de dinî nikahı oluyor. İkisi de planda yer kaplamalı, biri yalnızca 20 dakika sürse bile. Nikah salonunda fotoğraf çekilip çekilemeyeceğini ve tam olarak nerede durabileceğinizi önceden sorun – kurallar yere göre değişiyor.","## Giriş ve takı takma","Büyük düğünde iki program maddesi kesindir: çiftin girişi ve altın/para takma. İkincisi kalabalık ailelerde 45 dakikayı bulabilir ve misafirler için en önemli anlardan biridir – buna rağmen akış planında düzenli olarak unutulur.","## İki dillilik işi kolaylaştırır","Bir anneanne yalnızca Türkçe, sağdıç yalnızca Almanca konuşuyorsa, grup fotoğraflarının ne kadar rahat geçeceğini anlaşma belirler. İki dili de konuşan bir ekip, kırk kişilik dizilimde rahatlıkla on dakika kazandırır – kareler de o oranda rahat çıkar.","## Akışta mutlaka olması gerekenler","Kına ritüeli, giriş, nikah, takı takma, ilk dans, halay. Bu maddelerin her biri için bir saat ve kabaca bir süre – günün komut verilmeden akması için fazlası gerekmiyor."],"en":["A German-Turkish wedding is rarely one day. Often it is two or three: the kına night, the registry office and the big celebration – sometimes spread over two weekends, sometimes on consecutive evenings. For photography that means above all: settle beforehand what happens when, and who has which role.","## The kına night is not a warm-up","Emotionally, the henna evening is often the most intense part of the whole celebration. The moment the bride\'s hand is closed while her mother-in-law places the gold coin inside it lasts perhaps 40 seconds. Change a lens in that time and you have missed it.","In practice that means: two cameras, no lens change during the ritual, and knowing in advance from which direction the bride will be led in. The light is usually warm and weak – fast prime lenses are not a luxury here but a requirement.","## Keep the registry office and the nikah apart","Many couples have a registry office ceremony and a nikah as well. Both need time in the plan, even if one of them only lasts 20 minutes. Ask beforehand whether photography is allowed in the ceremony room and exactly where you may stand – the rules differ from place to place.","## The entrance and the pinning of money","At the big celebration two items are fixed: the couple\'s entrance, and the pinning on of gold and money. The latter can take 45 minutes in large families and is one of the most important moments for the guests – and yet it is regularly forgotten in the timeline.","## Being bilingual makes the work easier","When one grandmother speaks only Turkish and the best man only German, understanding each other decides how relaxed the group pictures turn out. A team that speaks both languages easily saves ten minutes with 40 people – and the pictures look correspondingly more at ease.","## What belongs in the timeline","The kına ritual, the entrance, the nikah or the ceremony, the pinning of gold, the first dance, the halay. A time and a rough duration for each of these points – that is all it takes for the day to run without anyone giving commands."]},"date":"2026-07-30","seed":"lum-blog-kina","slug":"deutsch-tuerkische-hochzeit-fotografieren","title":{"de":"Deutsch-türkische Hochzeit: Was beim Fotografieren wirklich zählt","tr":"Alman-Türk düğünü: Fotoğrafta gerçekten önemli olan ne?","en":"A German-Turkish wedding: what really counts when photographing it"},"excerpt":{"de":"Zwei Feiern, zwei Familien, oft zwei Sprachen. Wer den Ablauf einer Kına-Nacht und eines Nikah kennt, verpasst die Momente nicht, auf die es ankommt – hier die Punkte, die im Zeitplan stehen müssen.","tr":"İki kutlama, iki aile, çoğu zaman iki dil. Kına gecesinin ve nikahın akışını bilen, önemli anları kaçırmaz – akışta mutlaka yer alması gereken noktalar.","en":"Two celebrations, two families, often two languages. Knowing how a kına night and a nikah run means not missing the moments that matter – here are the points that have to be in the timeline."},"citySlug":"stuttgart"}],"stats":{"years":"9","rating":"4,9 ★","delivery":"3","weddings":"180+"},"addons":[{"name":{"de":"Zweiter Fotograf (ganzer Tag)","tr":"İkinci fotoğrafçı (tüm gün)","en":"Second photographer (whole day)"},"price":"+ 450 €"},{"name":{"de":"Henna-Abend / Verlobung (3 Std.)","tr":"Kına gecesi / nişan (3 saat)","en":"Henna night / engagement (3 hrs)"},"price":"+ 490 €"},{"name":{"de":"After-Wedding-Shooting (2 Std.)","tr":"After-Wedding çekimi (2 saat)","en":"After-wedding shoot (2 hrs)"},"price":"+ 390 €"},{"name":{"de":"Fotoalbum 30×30 cm, 40 Seiten","tr":"Fotoğraf albümü 30×30 cm, 40 sayfa","en":"Photo album 30×30 cm, 40 pages"},"price":"+ 590 €"},{"name":{"de":"Digitale Einladung mit RSVP","tr":"RSVP\'li dijital davetiye","en":"Digital invitation with RSVP"},"price":"79 €"},{"name":{"de":"Anfahrt über 60 km","tr":"60 km üzeri yol","en":"Travel beyond 60 km"},"price":"0,40 €/km"}],"cities":[{"slug":"guenzburg","name":"Günzburg","kreis":{"de":"Landkreis Günzburg","tr":"Günzburg ilçesi","en":"Günzburg district"},"drive":{"de":"rund 25 Minuten","tr":"yaklaşık 25 dakika","en":"about 25 minutes"},"lead":{"de":"Hochzeitsfotograf und Videograf in Günzburg – die nächste Stadt von Krumbach aus, und die mit der geschlossensten Altstadt der Region.","tr":"Günzburg’da düğün fotoğrafçısı ve videografı – Krumbach’a en yakın şehir ve bölgenin en bütün kalmış eski kenti.","en":"Wedding photographer and videographer in Günzburg – the nearest town to Krumbach, and the one with the most complete old centre in the region."},"body":{"de":["Günzburg ist für uns Nachbarschaft. Wir sind in einer knappen halben Stunde da, und wir kennen die Stadt nicht von einer Ortsbesichtigung, sondern von Hochzeiten zu jeder Jahreszeit. Das merkt man an Kleinigkeiten: dass der Marktplatz zum Schloss hin ansteigt und Gruppenbilder deshalb von unten besser aussehen als von oben. Dass die Frauenkirche von Dominikus Zimmermann innen ein Licht hat, mit dem man ohne Blitz arbeiten kann, wenn man weiß, wo man steht.","Die Altstadt ist kompakt genug, dass Trauung, Sektempfang und Paarshooting ohne Umziehen der ganzen Gesellschaft funktionieren. Das ist mehr wert, als es klingt: Jede Fahrt zwischen zwei Orten kostet vierzig Minuten Stimmung. Wer am Nachmittag heiratet, hat vom Schlossplatz aus bis in den frühen Abend weiches Licht; danach wird es in den Gassen schnell dunkel, und wir gehen an die Günz oder in Richtung Stadtpark."],"tr":["Günzburg bizim için komşu demek. Yarım saatten kısa sürede oradayız ve şehri bir keşif gezisinden değil, her mevsimden düğünlerden tanıyoruz. Bu, küçük şeylerde belli oluyor: meydanın saraya doğru yükseldiğini, bu yüzden toplu fotoğrafların aşağıdan daha iyi durduğunu bilmek gibi. Ya da Dominikus Zimmermann’ın Frauenkirche’sinin içinde, nerede duracağınızı bilirseniz flaşsız çalışılabilecek bir ışık olduğunu.","Eski kent, nikâh, kokteyl ve çift çekimi bütün topluluğu taşımadan yapılabilecek kadar derli toplu. Bu kulağa geldiğinden daha değerli: iki yer arasındaki her yolculuk kırk dakikalık keyif götürüyor. Öğleden sonra evlenenler saray meydanından akşamın ilk saatlerine kadar yumuşak ışık buluyor; sonrasında dar sokaklar hızla kararıyor, biz de Günz kıyısına ya da şehir parkına doğru geçiyoruz."],"en":["Günzburg is our neighbourhood. We are there in barely half an hour, and we know the town not from a scouting visit but from weddings in every season. You notice it in small things: that the market square rises towards the palace, which is why group pictures look better from below than from above. That the Frauenkirche by Dominikus Zimmermann has a light inside you can work with without flash, if you know where to stand.","The old centre is compact enough that the ceremony, the drinks reception and the couple shoot work without moving the whole party. That is worth more than it sounds: every drive between two places costs forty minutes of mood. Couples marrying in the afternoon have soft light from the palace square into the early evening; after that it gets dark quickly in the lanes, and we move to the Günz or towards the town park."]},"spots":[{"name":"Marktplatz und Schlossplatz","note":{"de":"Der Aufstieg zum Schloss gibt Tiefe. Vormittags liegt die Westseite im Schatten – dann lieber die Häuserzeile gegenüber.","tr":"Saraya çıkan eğim derinlik veriyor. Sabahları batı yüzü gölgede – o saatte karşıdaki sıra evler daha iyi.","en":"The climb up to the palace gives depth. In the morning the west side is in shadow – then use the row of houses opposite instead."}},{"name":"Frauenkirche","note":{"de":"Heller Rokoko-Innenraum, der ohne zusätzliches Licht auskommt. Fotografieren nur nach Absprache mit der Pfarrei.","tr":"Ek ışık gerektirmeyen aydınlık rokoko iç mekân. Çekim yalnızca kilise idaresiyle konuşulduktan sonra.","en":"A bright rococo interior that needs no extra light. Photography only by arrangement with the parish."}},{"name":"Günzufer und Auwald","note":{"de":"Grün und ruhig, fünf Gehminuten aus der Altstadt. Die letzte Stunde vor Sonnenuntergang gehört hierher.","tr":"Yeşil ve sakin, eski kentten beş dakika yürüyüş. Gün batımından önceki son saat buraya ait.","en":"Green and quiet, a five-minute walk from the old centre. The last hour before sunset belongs here."}}],"faq":[{"q":{"de":"Kommt ihr auch für eine kleine Trauung ohne Feier?","tr":"Kutlamasız küçük bir nikâh için de gelir misiniz?","en":"Do you also come for a small ceremony without a celebration?"},"a":{"de":"Ja. Für Günzburg gibt es dafür eine kurze Begleitung von zwei Stunden – Trauung, Gratulation, ein Rundgang durch die Altstadt. Anfahrt berechnen wir im Landkreis Günzburg nicht.","tr":"Evet. Günzburg için iki saatlik kısa bir eşlik var – nikâh, tebrikler, eski kentte bir tur. Günzburg ilçesi içinde yol ücreti almıyoruz.","en":"Yes. For Günzburg there is a short two-hour coverage for that – the ceremony, the congratulations, a walk through the old centre. We do not charge for travel within the Günzburg district."}},{"q":{"de":"Lohnt sich Legoland als Kulisse?","tr":"Legoland fon olarak işe yarar mı?","en":"Is Legoland worth using as a backdrop?"},"a":{"de":"Für Hochzeitsbilder eher nicht – es ist ein Freizeitpark mit eigenen Regeln und vielen Menschen im Bild. Wenn Familie mit Kindern angereist ist, planen wir es lieber als eigenen Programmpunkt am Folgetag ein.","tr":"Düğün fotoğrafı için pek değil – kendi kuralları ve karede çok insan olan bir eğlence parkı. Çocuklu aile geldiyse onu ertesi güne ayrı bir program olarak koymayı tercih ediyoruz.","en":"For wedding pictures, not really – it is a theme park with its own rules and a lot of people in the frame. If family with children has travelled in, we would rather plan it as its own event the following day."}}],"venues":[],"neighbours":["ulm","neu-ulm","augsburg","memmingen"]},{"slug":"ulm","name":"Ulm","kreis":{"de":"Stadtkreis Ulm, Baden-Württemberg","tr":"Ulm şehri, Baden-Württemberg","en":"Ulm urban district, Baden-Württemberg"},"drive":{"de":"rund 40 Minuten","tr":"yaklaşık 40 dakika","en":"about 40 minutes"},"lead":{"de":"Hochzeitsfotograf und Videograf in Ulm – Münster, Fischerviertel und Donau auf engem Raum, mit dem schwierigsten und schönsten Licht der Region.","tr":"Ulm’da düğün fotoğrafçısı ve videografı – Münster, Fischerviertel ve Tuna dar bir alanda; bölgenin hem en zor hem en güzel ışığıyla.","en":"Wedding photographer and videographer in Ulm – minster, fishermen\'s quarter and the Danube in a small space, with the hardest and the most beautiful light in the region."},"body":{"de":["Ulm ist die Stadt in unserem Umkreis, in der man am meisten falsch machen kann. Der Münsterplatz ist weit und hell, und um die Mittagszeit steht die Sonne so, dass Gesichter unter den Augen dunkel werden. Wir legen Paarbilder deshalb selten dorthin, sondern in das Fischerviertel: schmale Gassen, Fachwerk, die Blau in mehreren Armen, und Schatten, der weich ist statt hart. Wer trotzdem das Münster im Bild haben will, bekommt es von der Herdbrücke oder von der Donaupromenade aus – mit Abstand, und ohne dass der Turm oben abgeschnitten ist.","Das zweite Thema in Ulm ist Publikum. Die Altstadt ist an Samstagnachmittagen voll, und ein Brautpaar bleibt dort nicht unbemerkt. Manche Paare genießen das, andere werden still davon. Wir sprechen das vorher an und planen entsprechend: entweder früh am Morgen, wenn die Gassen leer sind, oder in den Randlagen an der Donau, wo man zu zweit sein kann, ohne aus der Stadt zu fahren."],"tr":["Ulm, çevremizde en çok hata yapılabilecek şehir. Münster meydanı geniş ve parlak; öğle saatlerinde güneş öyle bir açıda ki gözlerin altı kararıyor. Bu yüzden çift fotoğraflarını oraya nadiren koyuyoruz, Fischerviertel’i tercih ediyoruz: dar sokaklar, ahşap cumbalar, birkaç kola ayrılan Blau deresi ve sert değil yumuşak gölge. Yine de karede Münster isteyenler onu Herdbrücke’den ya da Tuna kıyısından alıyor – mesafeyle ve kulenin tepesi kesilmeden.","Ulm’un ikinci konusu kalabalık. Eski kent cumartesi öğleden sonraları dolu ve gelin damat orada fark edilmeden kalmıyor. Bazı çiftler bundan keyif alıyor, bazıları sesini kesiyor. Bunu önceden konuşup ona göre planlıyoruz: ya sokaklar boşken sabah erken, ya da şehirden çıkmadan baş başa kalınabilen Tuna kıyısındaki kenar noktalarda."],"en":["Ulm is the town in our area where most can go wrong. Münsterplatz is wide and bright, and around midday the sun stands so that faces go dark under the eyes. That is why we rarely put couple pictures there, but into the fishermen\'s quarter instead: narrow lanes, timber framing, the Blau in several arms, and shadow that is soft rather than hard. Anyone who still wants the minster in frame gets it from the Herdbrücke or the Danube promenade – with distance, and without the tower cut off at the top.","The second subject in Ulm is the audience. The old centre is full on Saturday afternoons, and a wedding couple does not go unnoticed there. Some couples enjoy it, others go quiet. We raise it beforehand and plan accordingly: either early in the morning, when the lanes are empty, or on the edges by the Danube, where you can be alone together without leaving town."]},"spots":[{"name":"Fischerviertel","note":{"de":"Enge Gassen an der Blau, weiches Streiflicht bis in den Nachmittag. Kopfsteinpflaster – hohe Absätze vorher bedenken.","tr":"Blau kıyısında dar sokaklar, öğleden sonraya kadar yumuşak yan ışık. Arnavut kaldırımı – yüksek topuğu önceden düşünün.","en":"Narrow lanes along the Blau, soft grazing light into the afternoon. Cobblestones – think about high heels in advance."}},{"name":"Donaupromenade und Metzgerturm","note":{"de":"Weite und Wasser, das Münster im Hintergrund. Am späten Abend das beste Licht der Stadt.","tr":"Genişlik ve su, arkada Münster. Akşamın geç saatinde şehrin en iyi ışığı.","en":"Space and water, the minster in the background. Late in the evening, the best light in town."}},{"name":"Münsterplatz","note":{"de":"Groß und repräsentativ, aber hart im Mittagslicht und selten leer. Für Gruppenbilder besser am frühen Vormittag.","tr":"Büyük ve gösterişli ama öğle ışığında sert ve nadiren boş. Toplu fotoğraf için sabahın erken saati daha iyi.","en":"Large and imposing, but harsh in midday light and rarely empty. Better for group pictures early in the morning."}}],"faq":[{"q":{"de":"Braucht man in Ulm eine Genehmigung zum Fotografieren?","tr":"Ulm’da fotoğraf için izin gerekiyor mu?","en":"Do you need a permit to photograph in Ulm?"},"a":{"de":"Für ein Paar mit Fotograf im öffentlichen Raum in aller Regel nicht. Anders wird es bei Aufbauten, Drohne oder größeren Gruppen, die einen Weg blockieren – das klären wir vorher mit der Stadt, damit am Hochzeitstag niemand diskutiert.","tr":"Kamusal alanda fotoğrafçıyla bir çift için kural olarak gerekmiyor. Ekipman kurulumu, drone ya da yolu kapatacak büyük gruplar başka konu – onu düğün günü kimse tartışmasın diye önceden belediyeyle hallediyoruz.","en":"For a couple with a photographer in public space, as a rule no. It is different with rigging, a drone or larger groups blocking a path – we clear that with the city beforehand, so nobody is arguing on the wedding day."}},{"q":{"de":"Ulm oder Neu-Ulm – wo sollen wir fotografieren?","tr":"Ulm mu Neu-Ulm mu – nerede çekilelim?","en":"Ulm or Neu-Ulm – where should we photograph?"},"a":{"de":"Die Donau trennt beide, die Brücke braucht vier Minuten zu Fuß. Wir nutzen oft beides: die Altstadtseite für Enge und Fachwerk, die Neu-Ulmer Seite für Weite und den Blick zurück aufs Münster.","tr":"İkisini Tuna ayırıyor, köprü yürüyerek dört dakika. Çoğu zaman ikisini birden kullanıyoruz: dar sokak ve ahşap için eski kent tarafı, genişlik ve Münster’e dönük manzara için Neu-Ulm tarafı.","en":"The Danube separates the two and the bridge takes four minutes on foot. We often use both: the old-town side for closeness and timber framing, the Neu-Ulm side for openness and the view back to the minster."}}],"venues":[],"neighbours":["neu-ulm","guenzburg","memmingen","augsburg"]},{"slug":"neu-ulm","name":"Neu-Ulm","kreis":{"de":"Landkreis Neu-Ulm, Bayern","tr":"Neu-Ulm ilçesi, Bavyera","en":"Neu-Ulm district, Bavaria"},"drive":{"de":"rund 40 Minuten","tr":"yaklaşık 40 dakika","en":"about 40 minutes"},"lead":{"de":"Hochzeitsfotograf und Videograf in Neu-Ulm – die ruhige Seite der Donau, mit Platz für Gruppenbilder und dem Münster als Hintergrund.","tr":"Neu-Ulm’da düğün fotoğrafçısı ve videografı – Tuna’nın sakin yakası; toplu fotoğraf için yer ve arka planda Münster.","en":"Wedding photographer and videographer in Neu-Ulm – the quiet side of the Danube, with room for group pictures and the minster as a backdrop."},"body":{"de":["Neu-Ulm wird unterschätzt, weil die berühmte Stadt gegenüber liegt. Fotografisch ist genau das der Vorteil: Von hier aus hat man das Ulmer Münster im Bild, ohne im Gedränge davor zu stehen. Die Donaupromenade ist breit, das Ufer ist offen, und eine Hochzeitsgesellschaft von fünfzig Personen findet Platz, ohne dass jemand auf der Straße steht.","Der Glacis-Park ist der zweite Grund, warum wir gern hierherkommen. Alter Baumbestand, gepflegte Wege, im Sommer Schatten und im Herbst Farbe – und er ist groß genug, dass zwei Hochzeiten am selben Tag sich nicht begegnen. Für Paare, die es unaufgeregt mögen, ist Neu-Ulm oft die bessere Wahl als die Altstadt gegenüber, und die Bilder sagen trotzdem eindeutig, wo sie entstanden sind."],"tr":["Neu-Ulm hafife alınıyor, çünkü ünlü şehir tam karşıda. Fotoğraf açısından asıl avantaj bu: buradan Ulm Münster’i karede oluyor, önündeki kalabalığın içinde durmadan. Tuna kıyısı geniş, sahil açık; elli kişilik bir düğün topluluğu kimse yola taşmadan yerleşiyor.","Glacis Parkı buraya gelmeyi sevmemizin ikinci sebebi. Yaşlı ağaçlar, bakımlı yollar, yazın gölge, sonbaharda renk – ve aynı gün iki düğünün karşılaşmayacağı kadar büyük. Sakin seven çiftler için Neu-Ulm çoğu zaman karşıdaki eski kentten daha iyi bir tercih; fotoğraflar yine de nerede çekildiğini net söylüyor."],"en":["Neu-Ulm is underrated because the famous town lies opposite. Photographically that is exactly the advantage: from here you have Ulm minster in frame without standing in the crush in front of it. The Danube promenade is wide, the bank is open, and a wedding party of fifty finds room without anybody standing in the road.","The Glacis park is the second reason we like coming here. Old trees, well-kept paths, shade in summer and colour in autumn – and it is big enough that two weddings on the same day never meet. For couples who like things unhurried, Neu-Ulm is often the better choice than the old town opposite, and the pictures still say unmistakably where they were taken."]},"spots":[{"name":"Donauufer mit Blick aufs Münster","note":{"de":"Die Postkarte, ohne das Gedränge der anderen Seite. Am schönsten in der Stunde vor Sonnenuntergang.","tr":"Kartpostal manzarası, karşı yakanın kalabalığı olmadan. En güzeli gün batımından önceki saat.","en":"The postcard, without the crush on the other side. At its best in the hour before sunset."}},{"name":"Glacis-Park","note":{"de":"Alter Baumbestand, weicher Schatten auch mittags. Bei Regen tragen die Wege besser als Wiesenwege.","tr":"Yaşlı ağaçlar, öğlen bile yumuşak gölge. Yağmurda yollar çayır patikalarından daha iyi taşıyor.","en":"Old trees, soft shade even at midday. In rain the paths hold up better than meadow tracks."}},{"name":"Edwin-Scharff-Haus und Umfeld","note":{"de":"Klare Architektur direkt am Wasser – gute Gegenposition zum Fachwerk auf der Ulmer Seite.","tr":"Su kenarında yalın mimari – Ulm tarafındaki ahşap dokuya iyi bir karşıtlık.","en":"Clear architecture right by the water – a good counterpoint to the timber framing on the Ulm side."}}],"faq":[{"q":{"de":"Wir feiern in Ulm, aber die Trauung ist in Neu-Ulm. Geht das?","tr":"Kutlama Ulm’da, nikâh Neu-Ulm’da. Olur mu?","en":"We are celebrating in Ulm but the ceremony is in Neu-Ulm. Does that work?"},"a":{"de":"Das ist der Normalfall und kostet kaum Zeit – über die Brücke sind es wenige Minuten. Wir planen den Wechsel so, dass er in die Fahrt der Gesellschaft fällt und nicht extra Programm wird.","tr":"Bu olağan durum ve neredeyse hiç zaman almıyor – köprüden birkaç dakika. Geçişi topluluğun zaten yapacağı yolculuğa denk getiriyoruz, ayrı bir program olmasın diye.","en":"That is the normal case and it costs hardly any time – it is a few minutes over the bridge. We plan the change so that it falls into the party\'s own journey and does not become an extra item."}},{"q":{"de":"Gibt es Platz für ein Gruppenbild mit allen Gästen?","tr":"Bütün misafirlerle toplu fotoğraf için yer var mı?","en":"Is there room for a group picture with all the guests?"},"a":{"de":"Ja, und das ist hier leichter als in den meisten Altstädten. Am Donauufer und im Glacis-Park stehen achtzig Personen, ohne dass wir jemanden auf eine Mauer stellen müssen.","tr":"Evet, üstelik çoğu eski kentten daha kolay. Tuna kıyısında ve Glacis Parkı’nda seksen kişi, kimseyi duvara çıkarmadan yerleşiyor.","en":"Yes, and it is easier here than in most old towns. On the Danube bank and in the Glacis park eighty people fit without us having to stand anyone on a wall."}}],"venues":[],"neighbours":["ulm","guenzburg","memmingen","augsburg"]},{"slug":"memmingen","name":"Memmingen","kreis":{"de":"Kreisfreie Stadt, Tor zum Allgäu","tr":"Bağımsız şehir, Allgäu’ya açılan kapı","en":"Independent city, gateway to the Allgäu"},"drive":{"de":"rund 40 Minuten","tr":"yaklaşık 40 dakika","en":"about 40 minutes"},"lead":{"de":"Hochzeitsfotograf und Videograf in Memmingen – eine Altstadt, die auch bei Regen funktioniert, und der kürzeste Weg ins Allgäu.","tr":"Memmingen’de düğün fotoğrafçısı ve videografı – yağmurda da işleyen bir eski kent ve Allgäu’ya en kısa yol.","en":"Wedding photographer and videographer in Memmingen – an old town that works in the rain too, and the shortest way into the Allgäu."},"body":{"de":["Memmingen hat etwas, das im Sommer niemanden interessiert und im November alles rettet: Arkaden. Am Steuerhaus und rund um den Marktplatz kann man trocken stehen und trotzdem draußen sein. Wir haben hier Hochzeiten fotografiert, an denen es durchgehend geregnet hat, und die Bilder sehen nicht nach Notlösung aus. Für ein Datum im Spätherbst oder Vorfrühling ist das ein echtes Argument.","Der zweite Grund ist die Geschlossenheit. Der Marktplatz mit Rathaus und Steuerhaus, das Siebendächerhaus an der Stadtbach-Ecke, die Gassen dazwischen – das liegt alles in Gehweite, und es wirkt aus jedem Winkel wie eine Kulisse, die jemand aufgebaut hat. Wer von Memmingen ins Allgäu weiterfährt, hat außerdem nach zwanzig Minuten Wiesen und Berge im Rücken, wenn es das Paar in die Landschaft zieht."],"tr":["Memmingen’de yazın kimsenin umursamadığı, kasımda ise her şeyi kurtaran bir şey var: revaklar. Steuerhaus’ta ve meydanın çevresinde kuru durup yine de dışarıda olabiliyorsunuz. Burada baştan sona yağmur yağan düğünler çektik ve fotoğraflar mecburiyetten çekilmiş gibi durmuyor. Geç sonbahar ya da erken ilkbahar tarihi için bu gerçek bir gerekçe.","İkinci sebep bütünlük. Belediye ve Steuerhaus’lu meydan, dere köşesindeki Siebendächerhaus, aradaki sokaklar – hepsi yürüme mesafesinde ve her açıdan biri özellikle kurmuş gibi duruyor. Memmingen’den Allgäu’ya devam edenler, çift kırsala çekiliyorsa yirmi dakika sonra arkalarında çayır ve dağ buluyor."],"en":["Memmingen has something nobody cares about in summer and that saves everything in November: arcades. At the Steuerhaus and around the market square you can stand dry and still be outside. We have photographed weddings here where it rained without stopping, and the pictures do not look like a fallback. For a date in late autumn or early spring that is a real argument.","The second reason is how complete it feels. The market square with the town hall and the Steuerhaus, the Siebendächerhaus on the corner by the town stream, the lanes in between – it is all within walking distance, and from every angle it looks like a set someone built. Anyone driving on from Memmingen into the Allgäu also has meadows and mountains behind them after twenty minutes, if the couple is drawn to the landscape."]},"spots":[{"name":"Marktplatz mit Steuerhaus","note":{"de":"Die Arkaden sind der Regenplan. Auch bei Sonne guter Schatten, wenn der Platz zu hell wird.","tr":"Revaklar yağmur planı. Güneşte de, meydan fazla parlarken iyi bir gölge.","en":"The arcades are the rain plan. Good shade in sunshine too, when the square gets too bright."}},{"name":"Siebendächerhaus am Stadtbach","note":{"de":"Unverwechselbar und klein – gut für zwei Personen, nicht für die ganze Gesellschaft.","tr":"Ayırt edici ama küçük – iki kişilik, bütün topluluk için değil.","en":"Unmistakable and small – good for two people, not for the whole party."}},{"name":"Stadtmauer und Westertor","note":{"de":"Ruhiger als der Marktplatz, mit Grün davor. Am späten Nachmittag steht die Sonne günstig.","tr":"Meydandan sakin, önünde yeşillik. Öğleden sonranın geç saatinde güneş uygun açıda.","en":"Quieter than the market square, with greenery in front. Late afternoon the sun sits well."}}],"faq":[{"q":{"de":"Was, wenn es an unserem Termin regnet?","tr":"Tarihimizde yağmur yağarsa ne olacak?","en":"What if it rains on our date?"},"a":{"de":"In Memmingen ist das die Stadt mit dem besten Plan B im Umkreis. Wir gehen unter die Arkaden am Marktplatz, arbeiten mit den Torbögen und dem nassen Pflaster – Regen wird dann Teil der Bilder statt ihr Gegner.","tr":"Memmingen bu konuda çevredeki en iyi B planına sahip şehir. Meydandaki revakların altına geçiyor, kemerlerle ve ıslak taşla çalışıyoruz – yağmur o zaman fotoğrafların düşmanı değil parçası oluyor.","en":"In Memmingen you have the best plan B in the area. We go under the arcades on the market square and work with the archways and the wet cobbles – rain then becomes part of the pictures instead of their enemy."}},{"q":{"de":"Fahrt ihr von Memmingen aus weiter ins Allgäu?","tr":"Memmingen’den Allgäu’ya devam eder misiniz?","en":"Do you drive on from Memmingen into the Allgäu?"},"a":{"de":"Gern. Für Paare, die Berge im Bild haben möchten, planen wir ein Zeitfenster von rund zwei Stunden ein – Hin- und Rückweg mitgerechnet. Das lohnt sich nur bei gutem Wetter, und wir entscheiden es am Morgen des Hochzeitstags gemeinsam.","tr":"Memnuniyetle. Karede dağ isteyen çiftler için gidiş dönüş dahil yaklaşık iki saatlik bir pencere ayırıyoruz. Bu yalnızca hava iyiyse değer; kararı düğün sabahı birlikte veriyoruz.","en":"Gladly. For couples who want mountains in frame we plan a window of about two hours – the drive there and back included. It is only worth it in good weather, and we decide it together on the morning of the wedding day."}}],"venues":[],"neighbours":["ulm","neu-ulm","guenzburg","friedrichshafen"]},{"slug":"augsburg","name":"Augsburg","kreis":{"de":"Kreisfreie Stadt, Bayerisch-Schwaben","tr":"Bağımsız şehir, Bavyera-Suabya","en":"Independent city, Bavarian Swabia"},"drive":{"de":"rund 50 Minuten","tr":"yaklaşık 50 dakika","en":"about 50 minutes"},"lead":{"de":"Hochzeitsfotograf und Videograf in Augsburg – Renaissance im großen Maßstab, und die einzige Stadt der Region, in der Wasser Weltkulturerbe ist.","tr":"Augsburg’da düğün fotoğrafçısı ve videografı – büyük ölçekte Rönesans ve bölgede suyu dünya mirası olan tek şehir.","en":"Wedding photographer and videographer in Augsburg – the Renaissance on a grand scale, and the only town in the region where water is World Heritage."},"body":{"de":["Augsburg ist die repräsentativste Stadt in unserem Umkreis. Die Maximilianstraße ist breit wie ein Platz, das Rathaus mit dem Goldenen Saal ist keine Kulisse, sondern ein Bauwerk, das im Bild Gewicht hat, und die Fuggerei ist eine Straße für sich – die älteste bestehende Sozialsiedlung der Welt, mit Backsteinfassaden und Ruhe mitten in der Stadt. Wer Bilder möchte, die nach Anlass aussehen, findet hier mehr davon als irgendwo sonst zwischen Ulm und München.","Diese Größe hat eine Kehrseite: Augsburg braucht Zeit. Zwischen Perlachturm, Fuggerei und den Wasserläufen im Lechviertel liegen Wege, die man nicht in zwanzig Minuten macht, und die Innenstadt ist auf breite Straßen gebaut, nicht auf kurze. Wir planen für Augsburg deshalb ein größeres Fenster ein oder legen uns vorher auf zwei Orte fest, statt vier halb zu sehen. Für die Wasserläufe gilt: schmale Kanäle, historische Brunnen, und am Vormittag deutlich weniger Menschen als nachmittags."],"tr":["Augsburg çevremizdeki en gösterişli şehir. Maximilianstraße bir meydan kadar geniş; Altın Salon’lu belediye binası bir fon değil, karede ağırlığı olan bir yapı; Fuggerei ise kendi başına bir sokak – dünyanın ayakta kalmış en eski sosyal konut yerleşimi, tuğla cepheler ve şehrin ortasında sessizlik. Anlamına yakışan fotoğraflar isteyen, Ulm ile Münih arasında bunun en fazlasını burada bulur.","Bu büyüklüğün bir de öbür yüzü var: Augsburg zaman istiyor. Perlach Kulesi, Fuggerei ve Lech mahallesindeki su yolları arasında yirmi dakikada alınmayacak mesafeler var; şehir merkezi kısa yollar üzerine değil geniş caddeler üzerine kurulmuş. Bu yüzden Augsburg için ya daha geniş bir pencere ayırıyoruz ya da dördünü yarım görmektense önceden iki yere karar veriyoruz. Su yolları için şunu bilin: dar kanallar, tarihî çeşmeler ve sabahları öğleden sonraya göre belirgin biçimde az insan."],"en":["Augsburg is the most imposing town in our area. Maximilianstraße is as wide as a square, the town hall with its Golden Hall is not a backdrop but a building that carries weight in a picture, and the Fuggerei is a street of its own – the oldest social housing complex still in use anywhere, with brick façades and quiet in the middle of the city. Anyone who wants pictures that look like an occasion will find more of them here than anywhere else between Ulm and Munich.","That size has a downside: Augsburg needs time. Between the Perlach tower, the Fuggerei and the water channels of the Lechviertel there are distances you do not cover in twenty minutes, and the centre is built on wide streets, not short ones. So for Augsburg we plan a larger window, or settle on two places in advance rather than half-seeing four. For the channels: narrow canals, historic fountains, and considerably fewer people in the morning than in the afternoon."]},"spots":[{"name":"Fuggerei","note":{"de":"Backstein, Grün, kaum Durchgangsverkehr. Zutritt und Fotografieren nur nach Anmeldung – wir kümmern uns darum.","tr":"Tuğla, yeşil, neredeyse hiç geçiş trafiği yok. Giriş ve çekim yalnız randevuyla – onu biz hallediyoruz.","en":"Brick, greenery, hardly any through traffic. Entry and photography only with prior registration – we take care of that."}},{"name":"Rathausplatz und Perlachturm","note":{"de":"Große Fläche für große Gesellschaften. Mittags hart – dann in die Arkaden der Maximilianstraße ausweichen.","tr":"Kalabalık topluluklar için geniş alan. Öğlen sert – o saatte Maximilianstraße revaklarına geçmek gerekiyor.","en":"A large area for large parties. Harsh at midday – then move into the arcades of Maximilianstraße."}},{"name":"Lechviertel und Wasserläufe","note":{"de":"Schmale Kanäle und alte Handwerkerhäuser, ruhiger als das Zentrum. Vormittags am leersten.","tr":"Dar kanallar ve eski zanaatkâr evleri, merkezden sakin. En boş hâli sabah.","en":"Narrow canals and old craftsmen\'s houses, quieter than the centre. Emptiest in the morning."}}],"faq":[{"q":{"de":"Kann man in der Fuggerei heiraten oder fotografieren?","tr":"Fuggerei’de evlenilir ya da fotoğraf çekilir mi?","en":"Can you marry or photograph in the Fuggerei?"},"a":{"de":"Fotografieren ist nach Anmeldung möglich, es ist aber ein bewohntes Quartier und kein Fotostudio – wir arbeiten dort leise und ohne Aufbauten. Die Anmeldung übernehmen wir rechtzeitig vor dem Termin.","tr":"Çekim randevuyla mümkün ama orası bir stüdyo değil, insanların yaşadığı bir mahalle – sessiz ve kurulum yapmadan çalışıyoruz. Randevuyu tarihten önce biz alıyoruz.","en":"Photography is possible with prior registration, but it is a lived-in quarter and not a photo studio – we work there quietly and without rigging. We handle the registration in good time before the date."}},{"q":{"de":"Berechnet ihr für Augsburg Anfahrt?","tr":"Augsburg için yol ücreti alıyor musunuz?","en":"Do you charge travel for Augsburg?"},"a":{"de":"Nein. Augsburg liegt in dem Umkreis, den wir ohne Anfahrtskosten abdecken. Erst ab etwa 80 Kilometern kommt eine Pauschale dazu, und die steht dann im Angebot, bevor irgendetwas unterschrieben wird.","tr":"Hayır. Augsburg yol ücreti almadığımız çevrede kalıyor. Yaklaşık 80 kilometreden sonra sabit bir tutar ekleniyor ve o da hiçbir şey imzalanmadan önce teklifte yazıyor.","en":"No. Augsburg is inside the radius we cover without travel costs. Only from about 80 kilometres does a flat rate come on top, and it is then in the quote before anything is signed."}}],"venues":[],"neighbours":["guenzburg","ulm","muenchen","neu-ulm"]},{"slug":"muenchen","name":"München","kreis":{"de":"Landeshauptstadt Bayern","tr":"Bavyera eyalet başkenti","en":"State capital of Bavaria"},"drive":{"de":"rund 1 Stunde 15","tr":"yaklaşık 1 saat 15","en":"about 1 hour 15"},"lead":{"de":"Hochzeitsfotograf und Videograf in München – für Paare, die uns aus Schwaben mitnehmen, und für Feiern, die den Aufwand wert sind.","tr":"Münih’te düğün fotoğrafçısı ve videografı – bizi Suabya’dan yanında götüren çiftler ve bu emeğe değen kutlamalar için.","en":"Wedding photographer and videographer in Munich – for couples who take us along from Swabia, and for celebrations worth the effort."},"body":{"de":["München ist nicht unsere Nachbarschaft, und wir tun nicht so. Wir kommen hierher, weil Paare uns mitnehmen, die wir aus der Region kennen, oder weil eine Familie zwischen Schwaben und der Landeshauptstadt verteilt ist. Das ist ein anderer Auftrag als eine Hochzeit zwanzig Minuten von zu Hause: Wir reisen am Vorabend an, wenn der Tag früh beginnt, und wir planen mit mehr Puffer, weil in München jede Fahrt zwischen zwei Orten länger dauert, als der Kartendienst sagt.","Fotografisch ist die Stadt reich und streng zugleich. Der Schlosspark Nymphenburg und der Englische Garten sind großartig und öffentlich – mit allem, was dazugehört: Läufer im Hintergrund, andere Hochzeitsgesellschaften, und für gewerbliche Aufnahmen teils eigene Regeln. Die Arkaden am Odeonsplatz und die Isarauen sind unsere ruhigeren Gegenvorschläge. Was in München immer funktioniert, ist der frühe Morgen: um sieben gehört die Stadt für eine Stunde niemandem."],"tr":["Münih bizim mahallemiz değil ve öyleymiş gibi yapmıyoruz. Buraya, bölgeden tanıdığımız çiftler bizi yanında götürdüğü ya da bir aile Suabya ile başkent arasında dağıldığı için geliyoruz. Bu, evden yirmi dakikadaki bir düğünden başka bir iş: gün erken başlıyorsa bir akşam önceden geliyoruz ve daha geniş pay bırakıyoruz, çünkü Münih’te iki yer arası her yolculuk harita uygulamasının dediğinden uzun sürüyor.","Fotoğraf açısından şehir hem zengin hem katı. Nymphenburg Sarayı parkı ve İngiliz Bahçesi muhteşem ve halka açık – beraberinde geleniyle: arka planda koşucular, başka düğün toplulukları ve ticari çekim için yer yer ayrı kurallar. Odeonsplatz revakları ve Isar kıyıları bizim daha sakin karşı önerilerimiz. Münih’te her zaman işleyen şey sabahın erken saati: yedide şehir bir saatliğine kimsenin değil."],"en":["Munich is not our neighbourhood, and we do not pretend otherwise. We come here because couples we know from the region take us along, or because a family is spread between Swabia and the state capital. That is a different job from a wedding twenty minutes from home: we travel the evening before if the day starts early, and we plan with more slack, because in Munich every drive between two places takes longer than the map service says.","Photographically the city is rich and strict at the same time. The park at Nymphenburg and the English Garden are magnificent and public – with everything that comes with it: runners in the background, other wedding parties, and in places their own rules for commercial photography. The arcades at Odeonsplatz and the Isar meadows are our quieter counter-proposals. What always works in Munich is the early morning: at seven the city belongs to nobody for an hour."]},"spots":[{"name":"Schlosspark Nymphenburg","note":{"de":"Weite Achsen und Wasser. Für gewerbliche Aufnahmen gelten eigene Regeln – vorher klären, nicht vor Ort diskutieren.","tr":"Geniş akslar ve su. Ticari çekimin ayrı kuralları var – yerinde tartışmak yerine önceden halledin.","en":"Wide axes and water. Commercial photography has its own rules – settle it beforehand, do not argue about it on site."}},{"name":"Odeonsplatz und Hofgarten","note":{"de":"Arkaden als Regen- und Mittagsplan, Symmetrie für ruhige Bilder. Früh am Morgen fast leer.","tr":"Yağmur ve öğlen planı olarak revaklar, sakin kareler için simetri. Sabah erken neredeyse boş.","en":"Arcades as the rain and midday plan, symmetry for calm pictures. Almost empty early in the morning."}},{"name":"Isarauen","note":{"de":"Kies, Wasser und Bäume statt Architektur – der Gegenpol, wenn die Stadt zu viel wird.","tr":"Mimari yerine çakıl, su ve ağaç – şehir fazla geldiğinde karşı kutup.","en":"Gravel, water and trees instead of architecture – the counterweight when the city gets to be too much."}}],"faq":[{"q":{"de":"Was kostet die Anfahrt nach München?","tr":"Münih’e yol ücreti ne kadar?","en":"What does travel to Munich cost?"},"a":{"de":"Ab etwa 80 Kilometern kommt eine Anfahrtspauschale dazu; für München nennen wir sie im Angebot konkret, zusammen mit einer Übernachtung, falls der Tag vor acht Uhr beginnt oder nach Mitternacht endet. Nichts davon taucht später als Überraschung auf der Rechnung auf.","tr":"Yaklaşık 80 kilometreden sonra sabit bir yol ücreti ekleniyor; Münih için bunu teklifte açıkça yazıyoruz, gün sekizden önce başlıyor ya da gece yarısından sonra bitiyorsa konaklamayla birlikte. Hiçbiri sonradan faturada sürpriz olarak çıkmıyor.","en":"From about 80 kilometres a travel flat rate is added; for Munich we name it concretely in the quote, together with an overnight stay if the day begins before eight or ends after midnight. None of it turns up later as a surprise on the invoice."}},{"q":{"de":"Lohnt es sich, uns von so weit zu buchen?","tr":"Bu kadar uzaktan bizi tutmak mantıklı mı?","en":"Is it worth booking us from this far away?"},"a":{"de":"Ehrlich: nur, wenn die Bilder zu euch passen und nicht, weil wir günstiger wären. München hat gute Fotografen. Paare buchen uns von hier aus meist, weil sie uns aus der Familie oder von einer anderen Hochzeit kennen – und das ist ein guter Grund.","tr":"Dürüst olalım: yalnızca fotoğraflar size uyuyorsa; daha ucuz olduğumuz için değil. Münih’in iyi fotoğrafçıları var. Buradan bizi tutan çiftler çoğunlukla aileden ya da başka bir düğünden tanıyor – ve bu iyi bir sebep.","en":"Honestly: only if the pictures suit you, and not because we would be cheaper. Munich has good photographers. Couples mostly book us from here because they know us from the family or from another wedding – and that is a good reason."}}],"venues":[],"neighbours":["augsburg","guenzburg","memmingen"]},{"slug":"stuttgart","name":"Stuttgart","kreis":{"de":"Landeshauptstadt Baden-Württemberg","tr":"Baden-Württemberg eyalet başkenti","en":"State capital of Baden-Württemberg"},"drive":{"de":"rund 1 Stunde 30","tr":"yaklaşık 1 saat 30","en":"about 1 hour 30"},"lead":{"de":"Hochzeitsfotograf und Videograf in Stuttgart – die Richtung nach Westen, mit Weinbergen direkt über der Stadt.","tr":"Stuttgart’ta düğün fotoğrafçısı ve videografı – batı yönü; şehrin hemen üstünde bağlar.","en":"Wedding photographer and videographer in Stuttgart – the westward direction, with vineyards right above the city."},"body":{"de":["Stuttgart ist von Krumbach aus die längste Fahrt nach Westen, und für viele deutsch-türkische Familien in unserem Umkreis die Stadt, in der die Verwandtschaft wohnt. Genau deshalb fahren wir sie: Wenn eine Hälfte der Familie aus Schwaben kommt und die andere aus dem Stuttgarter Raum, ist die Feier oft dort, und der Fotograf kommt mit.","Die Stadt liegt in einem Kessel, und das ist fotografisch ihr größter Vorteil. Innerhalb von zehn Minuten ist man aus dem Zentrum in den Weinbergen, mit Blick über die Dächer – eine Kombination, die keine andere Stadt in unserem Gebiet so anbietet. Unten am Schlossplatz ist es großstädtisch und um die Mittagszeit hart im Licht; oben ist es still, und die Sonne geht über den Reben unter. Wer beides will, sollte zwei Stunden dafür einplanen und nicht vierzig Minuten."],"tr":["Stuttgart, Krumbach’tan batıya en uzun yolculuk ve çevremizdeki birçok Türk-Alman ailesi için akrabaların yaşadığı şehir. Tam bu yüzden gidiyoruz: ailenin bir yarısı Suabya’dan, diğeri Stuttgart bölgesinden geliyorsa kutlama çoğu zaman orada oluyor, fotoğrafçı da geliyor.","Şehir bir çanağın içinde ve fotoğraf açısından en büyük avantajı bu. Merkezden on dakikada bağların içindesiniz, çatıların üzerine bakan bir manzarayla – bölgemizdeki başka hiçbir şehrin böyle sunmadığı bir birleşim. Aşağıda saray meydanı büyük şehir gibi ve öğlen ışığı sert; yukarısı sessiz ve güneş asmaların ardında batıyor. İkisini birden isteyen kırk dakika değil iki saat ayırmalı."],"en":["From Krumbach, Stuttgart is the longest drive westwards, and for many German-Turkish families in our area it is the city where the relatives live. That is exactly why we drive it: when one half of the family comes from Swabia and the other from the Stuttgart area, the celebration is often there, and the photographer comes along.","The city sits in a basin, and photographically that is its greatest advantage. Within ten minutes you are out of the centre and in the vineyards, looking out over the roofs – a combination no other city in our area offers like this. Down at Schlossplatz it is metropolitan and harsh in light around midday; up top it is quiet, and the sun goes down over the vines. Anyone who wants both should plan two hours for it, not forty minutes."]},"spots":[{"name":"Weinberge über der Stadt","note":{"de":"Blick über die Dächer, goldene Stunde ohne Publikum. Steile Wege – Schuhe zum Wechseln mitnehmen.","tr":"Çatıların üzerine manzara, seyircisiz altın saat. Dik yollar – değiştirmek için ayakkabı alın.","en":"A view over the roofs, golden hour without an audience. Steep paths – bring shoes to change into."}},{"name":"Schlossplatz und Altes Schloss","note":{"de":"Großstädtisch und repräsentativ, mittags hart. Bei Regen tragen die Arkaden.","tr":"Büyük şehir havası ve gösterişli, öğlen sert. Yağmurda revaklar iş görüyor.","en":"Metropolitan and imposing, harsh at midday. In rain the arcades carry you."}},{"name":"Höhenpark Killesberg","note":{"de":"Weiches Abendlicht und Weitblick, ruhiger als das Zentrum.","tr":"Yumuşak akşam ışığı ve geniş manzara, merkezden sakin.","en":"Soft evening light and a long view, quieter than the centre."}}],"faq":[{"q":{"de":"Ihr sitzt in Schwaben – warum Stuttgart?","tr":"Siz Suabya’dasınız – neden Stuttgart?","en":"You are based in Swabia – why Stuttgart?"},"a":{"de":"Weil Familien selten an einem Ort wohnen. Wir fahren die Strecke regelmäßig für Paare, deren Verwandtschaft im Stuttgarter Raum lebt, und kennen die Stadt gut genug, um nicht am Hochzeitstag nach einem Platz zu suchen.","tr":"Çünkü aileler nadiren tek bir yerde oturuyor. Bu yolu, akrabaları Stuttgart bölgesinde yaşayan çiftler için düzenli olarak yapıyoruz ve şehri düğün günü yer aramayacak kadar tanıyoruz.","en":"Because families rarely live in one place. We drive the route regularly for couples whose relatives live in the Stuttgart area, and we know the city well enough not to be looking for a spot on the wedding day."}},{"q":{"de":"Kommt eine Übernachtung dazu?","tr":"Konaklama ekleniyor mu?","en":"Does an overnight stay come on top?"},"a":{"de":"Wenn die Feier bis in die Nacht geht, ja – wir fahren nach zwölf Stunden Arbeit keine anderthalb Stunden mehr im Dunkeln zurück. Das steht vorher im Angebot, nicht hinterher auf der Rechnung.","tr":"Kutlama gece geç saate kadar sürüyorsa evet – on iki saatlik işten sonra karanlıkta bir buçuk saat yol yapmıyoruz. Bu sonradan faturada değil, önceden teklifte yazıyor.","en":"If the celebration runs into the night, yes – after twelve hours of work we do not drive another hour and a half in the dark. That is in the quote beforehand, not on the invoice afterwards."}}],"venues":[],"neighbours":["ulm","muenchen","augsburg"]},{"slug":"friedrichshafen","name":"Friedrichshafen","kreis":{"de":"Bodenseekreis","tr":"Bodensee bölgesi","en":"Lake Constance district"},"drive":{"de":"rund 1 Stunde 40","tr":"yaklaşık 1 saat 40","en":"about 1 hour 40"},"lead":{"de":"Hochzeitsfotograf und Videograf in Friedrichshafen – Bodensee, offener Horizont und ein Licht, das vom Wasser zurückkommt.","tr":"Friedrichshafen’de düğün fotoğrafçısı ve videografı – Bodensee, açık ufuk ve sudan geri gelen bir ışık.","en":"Wedding photographer and videographer in Friedrichshafen – Lake Constance, an open horizon and a light that comes back off the water."},"body":{"de":["Am See ist das Licht anders, und das ist keine Floskel. Wasser wirft zurück, was von oben kommt, und füllt Schatten unter Augen und Kinn – das macht Portraits am Ufer weicher als in der Stadt. Dafür gibt es keinen Schutz: An einem klaren Julimittag ist die Promenade gnadenlos, und bei Wind kämpft jede Frisur. Wir planen Bodensee-Termine deshalb um die Tageszeit herum, nicht um den Ort.","Friedrichshafen selbst ist nüchterner als die Postkartenorte am See, und wir mögen das. Die Uferpromenade ist lang und offen, der Blick geht bei gutem Wetter bis an die Schweizer Berge, und der Zeppelin über dem Wasser ist ein Motiv, das es sonst nirgends gibt – wenn er fliegt, warten wir kurz. Für Paare, die Weite wollen statt Kulisse, ist das der richtige Ort in dieser Richtung."],"tr":["Gölde ışık başka ve bu bir laf kalabalığı değil. Su, yukarıdan geleni geri yansıtıyor ve gözlerin, çenenin altındaki gölgeyi dolduruyor – bu, kıyıdaki portreleri şehirdekinden yumuşak yapıyor. Buna karşılık korunak yok: açık bir temmuz öğlesinde sahil acımasız, rüzgârda her saç mücadele veriyor. Bu yüzden Bodensee tarihlerini yere göre değil, günün saatine göre planlıyoruz.","Friedrichshafen’in kendisi göldeki kartpostal kasabalarından daha sade ve bunu seviyoruz. Sahil uzun ve açık, hava iyiyse manzara İsviçre dağlarına kadar gidiyor, suyun üstündeki zeplin ise başka hiçbir yerde olmayan bir kare – uçuyorsa biraz bekliyoruz. Fon değil genişlik isteyen çiftler için bu yöndeki doğru yer burası."],"en":["By the lake the light is different, and that is not a figure of speech. Water throws back what comes from above and fills the shadows under eyes and chin – that makes portraits on the shore softer than in town. In exchange there is no shelter: on a clear July midday the promenade is merciless, and in wind every hairstyle is a fight. So we plan Lake Constance dates around the time of day, not around the place.","Friedrichshafen itself is more sober than the postcard villages on the lake, and we like that. The lakeside promenade is long and open, in good weather the view reaches the Swiss mountains, and the Zeppelin over the water is a subject you get nowhere else – when it flies, we wait a moment. For couples who want space rather than scenery, this is the right place in that direction."]},"spots":[{"name":"Uferpromenade und Hafen","note":{"de":"Offener Horizont, weiches Licht vom Wasser. Mittags ungeschützt – lieber die letzten zwei Stunden vor Sonnenuntergang.","tr":"Açık ufuk, sudan gelen yumuşak ışık. Öğlen korunaksız – gün batımından önceki son iki saat daha iyi.","en":"An open horizon, soft light off the water. Unsheltered at midday – better the last two hours before sunset."}},{"name":"Schlosskirche am See","note":{"de":"Zwei Türme direkt am Wasser, gut aus der Ferne. Innen nur nach Absprache mit der Gemeinde.","tr":"Su kenarında iki kule, uzaktan iyi duruyor. İçerisi yalnız cemaatle konuşulduktan sonra.","en":"Two towers right by the water, good from a distance. Inside only by arrangement with the parish."}},{"name":"Uferpark Richtung Manzell","note":{"de":"Bäume und Wiese als Windschutz, wenn es auf der Promenade zu böig wird.","tr":"Sahil fazla rüzgârlıysa siper olarak ağaç ve çayır.","en":"Trees and meadow as a windbreak, when it gets too gusty on the promenade."}}],"faq":[{"q":{"de":"Was, wenn es am See stürmt?","tr":"Gölde fırtına çıkarsa ne olur?","en":"What if it is stormy on the lake?"},"a":{"de":"Dann gehen wir vom offenen Ufer weg in den Uferpark oder in geschützte Innenhöfe. Wind ist am Bodensee kein Ausnahmefall, sondern eine Planungsgröße – wir schauen am Morgen auf die Vorhersage und verschieben eher die Uhrzeit als den Ort.","tr":"O zaman açık kıyıdan sahil parkına ya da korunaklı avlulara geçiyoruz. Bodensee’de rüzgâr istisna değil, planlama verisi – sabah tahmine bakıyor ve yeri değil saati kaydırıyoruz.","en":"Then we move away from the open shore into the lakeside park or into sheltered courtyards. Wind on Lake Constance is not an exception but a planning factor – we look at the forecast in the morning and move the hour rather than the place."}},{"q":{"de":"Bleibt ihr über Nacht?","tr":"Geceyi orada geçiriyor musunuz?","en":"Do you stay overnight?"},"a":{"de":"Bei Terminen am Bodensee in der Regel ja. Die Rückfahrt dauert fast zwei Stunden, und die letzten Bilder des Abends sind oft die besten – die wollen wir nicht wegen der Uhrzeit auslassen.","tr":"Bodensee tarihlerinde genelde evet. Dönüş neredeyse iki saat ve akşamın son kareleri çoğu zaman en iyileri – onları saat yüzünden atlamak istemiyoruz.","en":"For dates on Lake Constance, usually yes. The drive back takes almost two hours, and the last pictures of the evening are often the best – we do not want to leave those out because of the clock."}}],"venues":[],"neighbours":["memmingen","bregenz","st-gallen"]},{"slug":"bregenz","name":"Bregenz","kreis":{"de":"Vorarlberg, Österreich","tr":"Vorarlberg, Avusturya","en":"Vorarlberg, Austria"},"drive":{"de":"rund 2 Stunden","tr":"yaklaşık 2 saat","en":"about 2 hours"},"lead":{"de":"Hochzeitsfotograf und Videograf in Bregenz – wo der Bodensee an den Berg stößt, mit Aussicht vom Pfänder über drei Länder.","tr":"Bregenz’de düğün fotoğrafçısı ve videografı – Bodensee’nin dağa dayandığı yer; Pfänder’den üç ülkeye bakan manzara.","en":"Wedding photographer and videographer in Bregenz – where Lake Constance meets the mountain, with a view from the Pfänder across three countries."},"body":{"de":["Bregenz ist der einzige Ort in unserem Gebiet, an dem See und Berg direkt aneinanderstoßen. Vom Pfänder aus sieht man bei klarer Sicht über den Bodensee bis nach Deutschland und in die Schweiz – ein Bild, das kein anderer Ort auf dieser Liste hergibt. Der Weg nach oben geht mit der Seilbahn, und das ist Teil der Planung: Fahrzeiten, Betriebszeiten und eine Warteschlange an einem schönen Sonntag.","Unten ist Bregenz zweigeteilt. Die Seepromenade mit der Seebühne ist offen und modern, die Oberstadt mit dem Martinsturm ist eng, alt und deutlich ruhiger. Wir kombinieren das gern: eine Stunde oben in den Gassen, eine am Wasser. Was Paare aus Deutschland bedenken sollten: Bregenz liegt in Österreich. Für uns heißt das eine Auslandsanfahrt und eine andere Rechnungsstellung – beides klären wir vorher schriftlich, damit am Ende keine Frage offen ist."],"tr":["Bregenz, bölgemizde göl ile dağın doğrudan buluştuğu tek yer. Pfänder’den hava açıkken Bodensee’nin ötesinde Almanya ve İsviçre görünüyor – bu listedeki başka hiçbir yerin vermediği bir kare. Yukarı çıkış teleferikle ve bu planın parçası: sefer saatleri, çalışma saatleri ve güzel bir pazar günü kuyruk.","Aşağıda Bregenz ikiye ayrılıyor. Sahne’li göl sahili açık ve modern; Martinsturm’lu yukarı şehir dar, eski ve belirgin biçimde sakin. İkisini birleştirmeyi seviyoruz: bir saat yukarıda sokaklarda, bir saat su kenarında. Almanya’dan gelen çiftlerin bilmesi gereken: Bregenz Avusturya’da. Bizim için bu, yurt dışı yolculuğu ve farklı bir faturalandırma demek – ikisini de sonunda soru kalmasın diye önceden yazılı olarak netleştiriyoruz."],"en":["Bregenz is the only place in our area where lake and mountain meet directly. From the Pfänder, in clear conditions, you look across Lake Constance into Germany and into Switzerland – a picture no other place on this list can give. The way up is by cable car, and that is part of the planning: journey times, opening hours and a queue on a fine Sunday.","Down below, Bregenz is in two halves. The lakeside promenade with the floating stage is open and modern, the upper town with the Martinsturm is narrow, old and considerably quieter. We like to combine them: an hour up in the lanes, one by the water. What couples from Germany should bear in mind: Bregenz is in Austria. For us that means a foreign journey and different invoicing – we settle both in writing beforehand, so no question is left at the end."]},"spots":[{"name":"Pfänder","note":{"de":"Blick über den ganzen See. Seilbahnzeiten prüfen – bei Nebel im Tal ist oben oft Sonne, umgekehrt aber auch.","tr":"Bütün göle bakan manzara. Teleferik saatlerine bakın – vadide sis varken yukarısı çoğu zaman güneşli, tersi de olabiliyor.","en":"A view across the whole lake. Check the cable car times – with fog in the valley there is often sun up top, but it works the other way round too."}},{"name":"Seepromenade und Seebühne","note":{"de":"Weite und Wasser, modern. Während der Festspiele im Sommer voll und teils gesperrt.","tr":"Genişlik ve su, modern. Yaz festivali sırasında kalabalık ve yer yer kapalı.","en":"Space and water, modern. During the summer festival it is busy and partly closed off."}},{"name":"Oberstadt mit Martinsturm","note":{"de":"Enge Gassen, alter Putz, kaum Verkehr – der ruhige Gegenpol zum Ufer.","tr":"Dar sokaklar, eski sıva, neredeyse trafik yok – kıyının sakin karşıtı.","en":"Narrow lanes, old plaster, hardly any traffic – the quiet counterpoint to the shore."}}],"faq":[{"q":{"de":"Fahrt ihr für eine Hochzeit nach Österreich?","tr":"Bir düğün için Avusturya’ya gelir misiniz?","en":"Do you travel to Austria for a wedding?"},"a":{"de":"Ja. Anfahrt, Übernachtung und die steuerlichen Punkte einer Auslandsleistung stehen dafür im Angebot, bevor etwas unterschrieben wird. Wir machen das nicht oft, aber wir machen es sauber.","tr":"Evet. Yol, konaklama ve yurt dışı hizmetin vergisel tarafı, hiçbir şey imzalanmadan önce teklifte yazıyor. Bunu sık yapmıyoruz ama düzgün yapıyoruz.","en":"Yes. Travel, accommodation and the tax points of a service abroad are in the quote for it before anything is signed. We do not do it often, but we do it properly."}},{"q":{"de":"Lohnt sich der Pfänder am Hochzeitstag?","tr":"Düğün günü Pfänder’e çıkmak değer mi?","en":"Is the Pfänder worth it on the wedding day?"},"a":{"de":"Nur mit Zeitpuffer und guter Sicht. Wir rechnen mit rund anderthalb Stunden für Auffahrt, Bilder und Rückweg. Bei Hochnebel entscheiden wir am Morgen dagegen – ein Berg ohne Aussicht ist nur ein kalter Umweg.","tr":"Yalnızca zaman payı ve açık hava varsa. Çıkış, çekim ve dönüş için yaklaşık bir buçuk saat hesaplıyoruz. Alçak sis varsa sabah vazgeçiyoruz – manzarasız bir dağ yalnızca soğuk bir sapma olur.","en":"Only with slack in the schedule and good visibility. We reckon on about an hour and a half for the ride up, the pictures and the way back. In high fog we decide against it in the morning – a mountain without a view is just a cold detour."}}],"venues":[],"neighbours":["friedrichshafen","st-gallen","memmingen"]},{"slug":"st-gallen","name":"St. Gallen","kreis":{"de":"Kanton St. Gallen, Schweiz","tr":"St. Gallen kantonu, İsviçre","en":"Canton of St. Gallen, Switzerland"},"drive":{"de":"rund 2 Stunden 15","tr":"yaklaşık 2 saat 15","en":"about 2 hours 15"},"lead":{"de":"Hochzeitsfotograf und Videograf in St. Gallen – Stiftsbezirk, Erker und die weiteste Fahrt, die wir regelmäßig machen.","tr":"St. Gallen’de düğün fotoğrafçısı ve videografı – manastır bölgesi, cumbalar ve düzenli yaptığımız en uzun yol.","en":"Wedding photographer and videographer in St. Gallen – the abbey precinct, oriel windows and the longest drive we make regularly."},"body":{"de":["St. Gallen ist der äußerste Punkt unseres Gebiets, und wir nennen ihn trotzdem, weil die Fahrt sich für den Stiftsbezirk lohnt. Kathedrale und Stiftsbibliothek stehen auf der Welterbeliste, und der Platz davor hat eine Ruhe, die man in einer Stadt dieser Größe nicht erwartet. Fotografiert wird dort außen – die Bibliothek ist ein Buchmagazin, kein Ort für ein Brautkleid, und das respektieren wir.","Die Altstadt lebt von den Erkern: über hundert bemalte und geschnitzte Vorbauten an den Häusern, die schmalen Gassen Tiefe geben. Bei bedecktem Himmel ist das ideal, in praller Sonne wird es fleckig – hier ist ein grauer Tag ausnahmsweise die bessere Nachricht. Für Paare aus Deutschland gilt dasselbe wie für Bregenz: andere Währung, Zollformalitäten für Ausrüstung, eigene Rechnungsstellung. Wir haben das geregelt, aber es gehört vorher besprochen und nicht am Hochzeitsmorgen."],"tr":["St. Gallen bölgemizin en uç noktası ve yine de anıyoruz, çünkü yolculuk manastır bölgesi için değiyor. Katedral ve manastır kütüphanesi dünya mirası listesinde; önündeki meydanda bu büyüklükte bir şehirde beklenmeyecek bir sessizlik var. Çekim orada dışarıda oluyor – kütüphane bir kitap deposu, gelinlik için bir mekân değil ve buna saygı duyuyoruz.","Eski kent cumbalarla yaşıyor: evlerin üzerinde yüzden fazla boyalı ve oymalı çıkma, dar sokaklara derinlik veriyor. Kapalı havada bu ideal, tepedeki güneşte lekeli oluyor – burada gri bir gün istisnai olarak iyi haber. Almanya’dan gelen çiftler için Bregenz’le aynısı geçerli: başka para birimi, ekipman için gümrük işlemleri, ayrı faturalandırma. Bunu çözdük ama düğün sabahı değil, önceden konuşulması gerekiyor."],"en":["St. Gallen is the outermost point of our area, and we name it anyway, because the drive is worth it for the abbey precinct. The cathedral and the abbey library are on the World Heritage list, and the square in front of them has a calm you would not expect in a city this size. Photography there happens outside – the library is a book repository, not a place for a wedding dress, and we respect that.","The old town lives on its oriels: over a hundred painted and carved bays on the houses, giving the narrow lanes depth. Under an overcast sky that is ideal; in full sun it goes blotchy – here, for once, a grey day is the better news. For couples from Germany the same applies as for Bregenz: a different currency, customs formalities for equipment, separate invoicing. We have that sorted, but it belongs in the conversation beforehand and not on the wedding morning."]},"spots":[{"name":"Stiftsbezirk","note":{"de":"Kathedrale und Klosterhof, Welterbe. Außenaufnahmen; innen gelten strenge Regeln.","tr":"Katedral ve manastır avlusu, dünya mirası. Dış çekim; içeride katı kurallar var.","en":"Cathedral and abbey courtyard, World Heritage. Exterior shots; strict rules apply inside."}},{"name":"Altstadt mit den Erkern","note":{"de":"Über hundert bemalte Vorbauten. Bei bedecktem Himmel am besten, harte Sonne macht Flecken.","tr":"Yüzden fazla boyalı çıkma. En iyisi kapalı havada; sert güneş leke yapıyor.","en":"Over a hundred painted bays. Best under an overcast sky, hard sun makes them blotchy."}},{"name":"Drei Weieren über der Stadt","note":{"de":"Weiher und Blick über St. Gallen, zwanzig Minuten vom Zentrum. Am Wochenende belebt.","tr":"Göletler ve şehre bakan manzara, merkezden yirmi dakika. Hafta sonu hareketli.","en":"A pond and a view over St. Gallen, twenty minutes from the centre. Busy at weekends."}}],"faq":[{"q":{"de":"Kann man in der Stiftsbibliothek fotografieren?","tr":"Manastır kütüphanesinde fotoğraf çekilir mi?","en":"Can you photograph in the abbey library?"},"a":{"de":"Nein, und das sollte man auch nicht wollen. Es ist ein Bibliotheksraum mit jahrhundertealten Beständen und entsprechendem Klima. Wir fotografieren im Klosterhof und am Platz davor – das gibt die Architektur genauso wieder.","tr":"Hayır ve istenmemeli de. Orası yüzyıllık koleksiyonları ve ona göre iklimi olan bir kütüphane salonu. Biz manastır avlusunda ve önündeki meydanda çekiyoruz – mimariyi o da aynı şekilde veriyor.","en":"No, and you should not want to. It is a library room with centuries-old holdings and a climate to match. We photograph in the abbey courtyard and on the square in front – that gives you the architecture just as well."}},{"q":{"de":"Rechnet ihr in Euro oder Franken ab?","tr":"Euro mu Frank mı üzerinden faturalıyorsunuz?","en":"Do you invoice in euros or francs?"},"a":{"de":"In Euro, mit einem festen Betrag im Angebot – kein Kurs, der sich bis zur Hochzeit bewegt. Anfahrt und Übernachtung stehen getrennt daneben, damit ihr seht, wofür ihr zahlt.","tr":"Euro üzerinden ve teklifte sabit tutarla – düğüne kadar oynayan bir kur yok. Yol ve konaklama yanında ayrı yazıyor, neye ödediğinizi görün diye.","en":"In euros, with a fixed amount in the quote – no exchange rate that moves before the wedding. Travel and accommodation stand separately next to it, so you can see what you are paying for."}}],"venues":[],"neighbours":["bregenz","friedrichshafen","memmingen"]}],"venues":[{"faq":[{"a":{"de":"Ja, mehrfach. Wir kennen die Abläufe der Schlossverwaltung, die Wege für kurze Umbaupausen und die Stellen, an denen auch samstags keine Besuchergruppen im Bild stehen.","tr":"Evet, birçok kez. Saray idaresinin işleyişini, kısa aralarda kullanılan geçişleri ve cumartesileri bile ziyaretçi grubunun kadraja girmediği noktaları biliyoruz.","en":"Yes, several times. We know how the palace administration works, the routes for short changeover breaks and the places where no visitor groups end up in frame, even on a Saturday."},"q":{"de":"Habt ihr schon auf Schloss Solitude fotografiert?","tr":"Schloss Solitude\'da daha önce çekim yaptınız mı?","en":"Have you photographed at Schloss Solitude before?"}},{"a":{"de":"40 Minuten reichen aus. Wenn ihr die Sichtachse und die Terrasse wollt, planen wir sie in die Stunde vor Sonnenuntergang.","tr":"40 dakika yeterli. Eksen ve terası istiyorsanız bunu gün batımından önceki saate planlıyoruz.","en":"40 minutes is enough. If you want the sightline and the terrace, we plan them into the hour before sunset."},"q":{"de":"Wie viel Zeit braucht ihr für das Paarshooting am Schloss?","tr":"Sarayda çift çekimi için ne kadar süre gerekiyor?","en":"How much time do you need for the couple shoot at the palace?"}}],"body":{"de":["Schloss Solitude gehört zu den schönsten Trauorten der Region: die weiße Rokoko-Fassade, die lange Sichtachse Richtung Ludwigsburg und eine Terrasse, die abends im warmen Gegenlicht liegt. Für die Fotografie heißt das vor allem eines – hier entstehen große, ruhige Bilder, wenn man den richtigen Zeitpunkt trifft.","Weil das Schloss tagsüber öffentlich zugänglich ist, planen wir das Paarshooting bewusst in die Randzeiten. Zwischen 18:00 und 19:30 Uhr wird es merklich ruhiger, gleichzeitig steht die Sonne tief über der Sichtachse. Wir reservieren dafür rund 40 Minuten und sind rechtzeitig zurück, bevor der Empfang beginnt.","Für die Trauung selbst arbeiten wir ohne Blitz und mit lichtstarken Festbrennweiten. Die Fenster im Weißen Saal geben genug Licht für saubere, natürliche Aufnahmen – auch im Winter."],"tr":["Schloss Solitude bölgenin en güzel nikah mekânlarından biri: beyaz rokoko cephe, Ludwigsburg yönüne uzanan görüş ekseni ve akşamları sıcak kontra ışıkta kalan teras. Fotoğraf açısından bu şu demek – doğru saati tutturursanız burada büyük, sakin kareler çıkıyor.","Saray gündüz halka açık olduğu için çift çekimini bilerek sakin saatlere alıyoruz. 18:00–19:30 arası gözle görülür şekilde boşalıyor, aynı anda güneş de eksenin üzerinde alçalıyor. Buna yaklaşık 40 dakika ayırıyor ve karşılama başlamadan geri dönüyoruz.","Nikahta flaş kullanmıyor, geniş diyaframlı sabit lenslerle çalışıyoruz. Beyaz Salon\'un pencereleri kışın bile temiz ve doğal kareler için yeterli ışık veriyor."],"en":["Schloss Solitude is one of the finest places to marry in the region: the white rococo façade, the long sightline towards Ludwigsburg and a terrace that lies in warm backlight in the evening. For photography that means one thing above all – large, calm pictures happen here if you hit the right moment.","Because the palace is open to the public during the day, we deliberately put the couple shoot into the edges of the day. Between 18:00 and 19:30 it gets noticeably quieter, and at the same time the sun stands low over the sightline. We set aside about 40 minutes for it and are back in good time before the reception starts.","For the ceremony itself we work without flash and with fast prime lenses. The windows in the White Hall give enough light for clean, natural pictures – in winter too."]},"city":"Stuttgart","lead":{"de":"Hochzeitsfotograf für Schloss Solitude in Stuttgart – wir kennen den Ablauf, das Licht auf der Terrasse und die ruhigen Ecken, wenn Tagesbesucher unterwegs sind.","tr":"Stuttgart Schloss Solitude için düğün fotoğrafçısı – akışı, terastaki ışığı ve ziyaretçi yoğunken sakin kalan köşeleri biliyoruz.","en":"Wedding photographer for Schloss Solitude in Stuttgart – we know the running order, the light on the terrace and the quiet corners when day visitors are about."},"name":"Schloss Solitude","slug":"schloss-solitude","type":{"de":"Schloss","tr":"Saray","en":"Palace"},"light":{"de":"Beste Zeit für Portraits: 60–90 Minuten vor Sonnenuntergang auf der Südterrasse. Mittags hartes Licht – dann besser die Arkaden nutzen.","tr":"Portre için en iyi zaman: gün batımından 60–90 dakika önce güney terası. Öğle saatlerinde ışık sert – o zaman revakları kullanmak daha iyi.","en":"Best time for portraits: 60–90 minutes before sunset on the south terrace. Hard light at midday – better to use the arcades then."},"rules":{"de":["Fotogenehmigung für gewerbliche Shootings über die Schlossverwaltung","Kein Blitz und keine Stative im Innenbereich während der Trauung","Drohnenaufnahmen nicht gestattet – wir arbeiten mit Gimbal und Slider"],"tr":["Ticari çekimler için saray idaresinden izin gerekiyor","Nikah sırasında iç mekânda flaş ve tripod yok","Drone yasak – gimbal ve slider ile çalışıyoruz"],"en":["Photo permit for commercial shoots through the palace administration","No flash and no tripods indoors during the ceremony","Drone footage not permitted – we work with gimbal and slider"]},"spots":{"de":["Sichtachse Richtung Ludwigsburg – lange Perspektive, ideal für Weitwinkel","Südterrasse mit Blick ins Tal – goldene Stunde","Arkadengang – Schattenlicht auch bei Mittagssonne","Kavaliersbauten – symmetrische Architekturbilder"],"tr":["Ludwigsburg yönündeki eksen – uzun perspektif, geniş açı için ideal","Vadiye bakan güney terası – altın saat","Revaklı geçit – öğle güneşinde bile gölge ışığı","Yan binalar – simetrik mimari kareler"],"en":["Sightline towards Ludwigsburg – a long perspective, ideal for wide angle","South terrace with a view into the valley – golden hour","Arcade walk – shaded light even in midday sun","The cavalier buildings – symmetrical architectural pictures"]},"timing":[{"time":"14:00","what":{"de":"Getting Ready im Hotel, Anfahrt ca. 20 Min. aus der Innenstadt","tr":"Otelde hazırlık, merkezden yaklaşık 20 dk yol","en":"Getting ready at the hotel, about 20 min. from the city centre"}},{"time":"15:30","what":{"de":"Trauung im Weißen Saal – verfügbares Licht, kein Blitz","tr":"Beyaz Salon\'da nikah – mevcut ışık, flaşsız","en":"Ceremony in the White Hall – available light, no flash"}},{"time":"16:15","what":{"de":"Gratulation & Gruppenbilder vor der Hauptfassade","tr":"Tebrikler ve ana cephede grup fotoğrafları","en":"Congratulations & group pictures in front of the main façade"}},{"time":"18:30","what":{"de":"Paarshooting Sichtachse & Terrasse (40 Min.)","tr":"Görüş ekseni ve terasta çift çekimi (40 dk)","en":"Couple shoot on the sightline & terrace (40 min.)"}},{"time":"20:00","what":{"de":"Feier – Blitz mit Bounce, Bühnenbereich mit zweiter Kamera","tr":"Düğün – sektirmeli flaş, sahne için ikinci kamera","en":"Celebration – bounced flash, stage area with a second camera"}}],"address":"Solitude 1, 70197 Stuttgart","capacity":{"de":"bis ca. 120 Gäste","tr":"yaklaşık 120 kişiye kadar","en":"up to about 120 guests"},"citySlug":"stuttgart","placeId":"","lat":"","lng":""},{"faq":[{"a":{"de":"Auf Wunsch ja. Wir übernehmen die Anmeldung und stimmen den Zeitraum so ab, dass er in euren Ablauf passt. Die Gebühr wird direkt mit dem Betreiber abgerechnet.","tr":"İsterseniz evet. Başvuruyu biz yapıyor, saati programınıza uyacak şekilde ayarlıyoruz. Ücret doğrudan işletmeye ödeniyor.","en":"On request, yes. We handle the application and agree the time slot so that it fits your running order. The fee is settled directly with the operator."},"q":{"de":"Kümmert ihr euch um die Fotogenehmigung im Blühenden Barock?","tr":"Blühendes Barock çekim iznini siz mi alıyorsunuz?","en":"Do you take care of the photo permit in the Blühendes Barock?"}},{"a":{"de":"Sehr. Die beleuchtete Fassade ergibt zwei bis drei Bilder, die man im Album später garantiert groß druckt – und es kostet euch nur zehn Minuten Feier.","tr":"Kesinlikle. Aydınlatılmış cephe, albümde büyük basacağınız iki üç kare veriyor – size sadece on dakikaya mal oluyor.","en":"Very much. The lit façade gives two or three pictures you will certainly print large in the album later – and it costs you only ten minutes of the celebration."},"q":{"de":"Lohnt sich ein Shooting zur blauen Stunde?","tr":"Mavi saat çekimi değer mi?","en":"Is a shoot at the blue hour worth it?"}}],"body":{"de":["Das Residenzschloss ist eine der größten barocken Schlossanlagen Deutschlands – und für die Fotografie ein Geschenk: symmetrische Innenhöfe, lange Fluchten, immer eine Wand im Schatten. Selbst an einem grellen Julitag findet man hier innerhalb von fünf Gehminuten weiches Licht.","Viele Paare kombinieren die Trauung im Schloss mit einem Shooting im Blühenden Barock. Das lohnt sich, braucht aber Planung: die Genehmigung muss vorab beantragt werden und der Weg vom Innenhof bis zu den Rosengärten dauert im Kleid gut zehn Minuten. Wir kalkulieren diesen Puffer von Anfang an mit ein.","Für den Abend gilt: die beleuchtete Fassade ergibt zur blauen Stunde – etwa 20 Minuten nach Sonnenuntergang – Bilder, die tagsüber nicht möglich sind. Zwei Minuten Unterbrechung der Feier reichen dafür völlig."],"tr":["Residenzschloss Almanya\'nın en büyük barok saray komplekslerinden biri – ve fotoğraf için tam bir hediye: simetrik iç avlular, uzun perspektifler, her saatte gölgede kalan bir duvar. Temmuzun en sert gününde bile beş dakika yürüyüşle yumuşak ışık bulunuyor.","Birçok çift saraydaki nikahı Blühendes Barock çekimiyle birleştiriyor. Buna değer ama planlama ister: izin önceden alınmalı ve iç avludan gül bahçelerine yürüyüş gelinlikle on dakikayı buluyor. Bu payı baştan hesaba katıyoruz.","Akşam için: aydınlatılmış cephe mavi saatte – gün batımından yaklaşık 20 dakika sonra – gündüz mümkün olmayan kareler veriyor. Bunun için düğüne iki dakika ara vermek yeterli."],"en":["The Residenzschloss is one of the largest baroque palace complexes in Germany – and a gift for photography: symmetrical courtyards, long lines of sight, always a wall in shade. Even on a glaring July day you find soft light here within a five-minute walk.","Many couples combine the ceremony in the palace with a shoot in the Blühendes Barock gardens. It is worth it, but it needs planning: the permit has to be applied for in advance and the walk from the courtyard to the rose gardens takes a good ten minutes in a dress. We build that slack in from the start.","For the evening: at the blue hour – about 20 minutes after sunset – the lit façade gives pictures that are not possible during the day. Two minutes away from the celebration is entirely enough for it."]},"city":"Ludwigsburg","lead":{"de":"Hochzeitsfotograf für das Residenzschloss Ludwigsburg – barocke Symmetrie, klare Bildsprache und ein Zeitplan, der zum Blühenden Barock passt.","tr":"Residenzschloss Ludwigsburg için düğün fotoğrafçısı – barok simetri, net görsel dil ve Blühendes Barock\'a uyan bir zaman planı.","en":"Wedding photographer for the Residenzschloss Ludwigsburg – baroque symmetry, a clear visual language and a timeline that fits the Blühendes Barock gardens."},"name":"Residenzschloss Ludwigsburg","slug":"residenzschloss-ludwigsburg","type":{"de":"Schloss","tr":"Saray","en":"Palace"},"light":{"de":"Innenhöfe liefern ganztags weiches Schattenlicht. Blaue Stunde an der Hauptfassade: ca. 20 Minuten nach Sonnenuntergang.","tr":"İç avlular gün boyu yumuşak gölge ışığı veriyor. Ana cephede mavi saat: gün batımından ~20 dakika sonra.","en":"The courtyards give soft shaded light all day. Blue hour at the main façade: about 20 minutes after sunset."},"rules":{"de":["Gewerbliche Fotografie im Blühenden Barock ist genehmigungs- und kostenpflichtig","Im Museumsbereich ist Blitzlicht untersagt","Fahrzeuge nur über die ausgewiesenen Zufahrten – Anfahrt großzügig planen"],"tr":["Blühendes Barock\'ta ticari çekim izinli ve ücretli","Müze bölümünde flaş yasak","Araçlar yalnızca belirlenen girişlerden – yol için bol zaman bırakın"],"en":["Commercial photography in the Blühendes Barock requires a permit and a fee","Flash is not allowed in the museum areas","Vehicles only via the marked entrances – allow plenty of time to arrive"]},"spots":{"de":["Nördlicher Innenhof – symmetrisch, weiches Licht","Treppenhaus mit Handlauf – klassisches Kleid-Detail","Rosengarten im Blühenden Barock – nur mit Genehmigung","Hauptfassade zur blauen Stunde – beleuchtet"],"tr":["Kuzey iç avlu – simetrik, yumuşak ışık","Trabzanlı merdiven – klasik gelinlik detayı","Blühendes Barock gül bahçesi – sadece izinle","Mavi saatte aydınlatılmış ana cephe"],"en":["Northern courtyard – symmetrical, soft light","Staircase with handrail – a classic dress detail","Rose garden in the Blühendes Barock – only with a permit","Main façade at the blue hour – lit"]},"timing":[{"time":"11:00","what":{"de":"Getting Ready, Detailaufnahmen von Ringen, Kleid und Papeterie","tr":"Hazırlık; yüzük, gelinlik ve davetiye detayları","en":"Getting ready, detail shots of rings, dress and stationery"}},{"time":"13:00","what":{"de":"Trauung – verfügbares Licht, zweite Kamera für Reaktionen der Gäste","tr":"Nikah – mevcut ışık, misafir tepkileri için ikinci kamera","en":"Ceremony – available light, second camera for the guests\' reactions"}},{"time":"14:00","what":{"de":"Sektempfang im Innenhof, lockere Reportage","tr":"İç avluda karşılama, serbest belgesel çekim","en":"Drinks reception in the courtyard, relaxed reportage"}},{"time":"15:30","what":{"de":"Shooting Blühendes Barock (Genehmigung erforderlich)","tr":"Blühendes Barock çekimi (izin gerekli)","en":"Shoot in the Blühendes Barock (permit required)"}},{"time":"21:30","what":{"de":"Blaue Stunde an der Hauptfassade – 10 Minuten","tr":"Ana cephede mavi saat – 10 dakika","en":"Blue hour at the main façade – 10 minutes"}}],"address":"Schlossstraße 30, 71634 Ludwigsburg","capacity":{"de":"je nach Saal 50–250 Gäste","tr":"salona göre 50–250 kişi","en":"50–250 guests depending on the hall"},"citySlug":"stuttgart"},{"faq":[{"a":{"de":"Nicht, wenn richtig geleuchtet wird. Wir arbeiten mit zwei entfesselten Blitzen und Vollformatkameras, dadurch bleiben die Aufnahmen sauber und die Hauttöne natürlich.","tr":"Doğru ışıkla hayır. İki harici flaş ve full frame gövdelerle çalışıyoruz; kareler temiz, ten tonları doğal kalıyor.","en":"Not if the lighting is done properly. We work with two off-camera flashes and full-frame cameras, which keeps the pictures clean and the skin tones natural."},"q":{"de":"Werden Bilder im dunklen Saal körnig?","tr":"Karanlık salonda kareler grenli çıkar mı?","en":"Do pictures get grainy in the dark hall?"}},{"a":{"de":"Ja. Ab 300 Gästen empfehlen wir zwei Fotografen und zwei Videografen, damit Bühne, Tische und Empfang gleichzeitig abgedeckt sind.","tr":"Evet. 300 kişiden itibaren iki fotoğrafçı ve iki videograf öneriyoruz; sahne, masalar ve karşılama aynı anda çekiliyor.","en":"Yes. From 300 guests we recommend two photographers and two videographers, so that the stage, the tables and the reception are covered at the same time."},"q":{"de":"Kommt ihr auch für Hochzeiten mit 600 Gästen?","tr":"600 kişilik düğünlere de geliyor musunuz?","en":"Do you also come for weddings with 600 guests?"}}],"body":{"de":["Große Säle sind fotografisch anspruchsvoll: viel Mischlicht, farbige LED-Spots, dunkle Decken, an denen sich kein Blitz sauber bouncen lässt. Wer hier gute Bilder will, braucht ein Team, das mit entfesseltem Licht arbeitet – nicht nur mit dem Blitz auf der Kamera.","Wir bauen im SI-Centrum in der Regel zwei Blitzstative an den Saalrändern auf. Das ergibt saubere Trennung vom Hintergrund, natürliche Hauttöne und Bilder vom Einzug, die nicht flach wirken. Parallel filmt das Video-Team mit Gimbal – abgestimmt, damit sich Foto und Video nicht gegenseitig im Bild stehen.","Weil Hotel, Säle und Parkhaus im selben Komplex liegen, sind die Wege kurz. Das Getting Ready findet meist im Hotelzimmer statt: Fenster nach Süden, gute Größe, wir arbeiten dort ausschließlich mit Tageslicht."],"tr":["Büyük salonlar fotoğraf açısından zorlu: karışık ışık, renkli LED spotlar, flaşın sektirilemediği koyu tavanlar. Burada iyi kare isteyen çift, sadece kamera üstü flaşla değil harici ışıkla çalışan bir ekibe ihtiyaç duyar.","SI-Centrum\'da genelde salonun iki kenarına flaş ayağı kuruyoruz. Bu, arka plandan temiz ayrışma, doğal ten tonları ve düz görünmeyen giriş kareleri veriyor. Aynı anda video ekibi gimbal ile çekiyor – foto ve video birbirinin kadrajına girmeyecek şekilde koordineli.","Otel, salonlar ve otopark aynı kompleks içinde olduğu için mesafeler kısa. Hazırlık genelde otel odasında: güneye bakan pencere, geniş oda; orada sadece gün ışığıyla çalışıyoruz."],"en":["Large halls are demanding photographically: a lot of mixed light, coloured LED spots, dark ceilings off which no flash bounces cleanly. Anyone who wants good pictures here needs a team that works with off-camera light – not just the flash on the camera.","At the SI-Centrum we usually set up two flash stands at the edges of the hall. That gives clean separation from the background, natural skin tones and entrance pictures that do not look flat. In parallel the video team films with a gimbal – coordinated, so that photo and video do not end up in each other\'s frame.","Because the hotel, the halls and the car park are in the same complex, the distances are short. Getting ready usually happens in the hotel room: south-facing windows, a good size, and we work there with daylight only."]},"city":"Stuttgart","lead":{"de":"Hochzeitsfotograf & Videograf im SI-Centrum Stuttgart – erfahren mit großen Feiern, Bühnenprogramm und schwierigem Kunstlicht.","tr":"SI-Centrum Stuttgart\'ta düğün fotoğrafçısı ve videografı – büyük düğünler, sahne programı ve zor yapay ışıkta tecrübeli.","en":"Wedding photographer & videographer at the SI-Centrum Stuttgart – experienced with large celebrations, stage programmes and difficult artificial light."},"name":"SI-Centrum Stuttgart","slug":"si-centrum-stuttgart","type":{"de":"Eventlocation & Hotel","tr":"Etkinlik mekânı & otel","en":"Event venue & hotel"},"light":{"de":"Sehr dunkler Saal, farbiges Kunstlicht. Wir arbeiten mit zwei entfesselten Blitzen plus lichtstarken Objektiven (f/1.4–1.8).","tr":"Çok karanlık salon, renkli yapay ışık. İki harici flaş ve geniş diyaframlı lenslerle (f/1.4–1.8) çalışıyoruz.","en":"A very dark hall with coloured artificial light. We work with two off-camera flashes plus fast lenses (f/1.4–1.8)."},"rules":{"de":["Absprache mit der Haustechnik wegen Bühnenlicht und Nebelmaschine","Stative im Gästebereich nur am Rand","Zeitfenster für Dekoraufnahmen vor Einlass mit dem Veranstalter klären"],"tr":["Sahne ışığı ve sis makinesi için teknik ekiple görüşme","Misafir alanında tripodlar yalnızca kenarda","Süsleme çekimi için giriş öncesi zaman aralığını organizatörle netleştirin"],"en":["Agree stage lighting and smoke machines with the house technicians","Tripods in the guest area only at the edges","Clear the time slot for décor shots before doors open with the organiser"]},"spots":{"de":["Hotelzimmer am Fenster – Getting Ready mit weichem Tageslicht","Foyer mit Glasfront – Empfangsbilder ohne Blitz","Bühne & Einzug – entfesseltes Blitzsetup","Außenbereich Richtung Filderpark für 20 Minuten Paarzeit"],"tr":["Otel odasında pencere kenarı – yumuşak gün ışığında hazırlık","Cam cepheli fuaye – flaşsız karşılama kareleri","Sahne ve giriş – harici flaş kurulumu","20 dakikalık çift çekimi için Filderpark yönündeki dış alan"],"en":["Hotel room by the window – getting ready in soft daylight","Foyer with a glass front – reception pictures without flash","Stage & entrance – off-camera flash setup","Outside area towards the Filderpark for 20 minutes of couple time"]},"timing":[{"time":"13:00","what":{"de":"Getting Ready im Hotelzimmer – Tageslicht am Fenster","tr":"Otel odasında hazırlık – pencerede gün ışığı","en":"Getting ready in the hotel room – daylight at the window"}},{"time":"16:00","what":{"de":"First Look & Paarshooting draußen, bevor die Gäste eintreffen","tr":"İlk görüşme ve dışarıda çift çekimi, misafirler gelmeden","en":"First look & couple shoot outside, before the guests arrive"}},{"time":"18:00","what":{"de":"Empfang, Saaldekor und Details vor dem Einzug","tr":"Karşılama, salon süslemesi ve giriş öncesi detaylar","en":"Reception, hall décor and details before the entrance"}},{"time":"19:00","what":{"de":"Einzug mit Bühnenlicht – zwei Fotografen, zwei Perspektiven","tr":"Sahne ışığında giriş – iki fotoğrafçı, iki açı","en":"Entrance under stage lighting – two photographers, two perspectives"}},{"time":"22:00","what":{"de":"Party, Konfetti, offene Reportage bis Ende","tr":"Parti, konfeti, sona kadar serbest çekim","en":"Party, confetti, open reportage until the end"}}],"address":"Plieninger Straße 100, 70567 Stuttgart","capacity":{"de":"bis ca. 800 Gäste","tr":"yaklaşık 800 kişiye kadar","en":"up to about 800 guests"},"citySlug":"stuttgart"},{"faq":[{"a":{"de":"Der Aufstieg dauert etwa fünf Minuten. Wir planen 30 Minuten insgesamt ein – die Gäste merken kaum, dass ihr weg wart.","tr":"Çıkış yaklaşık beş dakika. Toplam 30 dakika planlıyoruz – misafirler ayrıldığınızı neredeyse fark etmiyor.","en":"The climb takes about five minutes. We plan 30 minutes in total – the guests barely notice you were gone."},"q":{"de":"Wie kommen wir in die Weinberge, ohne die Feier lange zu verlassen?","tr":"Düğünden uzun süre ayrılmadan bağlara nasıl çıkarız?","en":"How do we get to the vineyards without leaving the celebration for long?"}}],"body":{"de":["Die Alte Kelter ist eine der beliebtesten Hochzeitslocations im Rems-Murr-Kreis: massive Holzbalken, hohe Decken und ein Raumgefühl, das auch bei 400 Gästen nicht kalt wirkt. Fotografisch ist das Holz ein Vorteil – Blitzlicht bekommt hier eine warme, angenehme Färbung, statt wie in weißen Sälen flach zu wirken.","Der größte Trumpf liegt aber draußen: die Rebhänge am Kappelberg sind in fünf Minuten zu Fuß erreichbar. Wer die goldene Stunde nutzt, bekommt Portraits, die aussehen wie aus der Toskana – ohne die Feier länger als eine halbe Stunde zu verlassen.","Für den Ablauf empfehlen wir, den Einzug nicht zu spät zu legen. Wenn das Tageslicht durch die Hallenfenster noch mitspielt, entstehen deutlich lebendigere Bilder als bei reinem Kunstlicht."],"tr":["Alte Kelter, Rems-Murr bölgesinin en sevilen düğün mekânlarından biri: kalın ahşap kirişler, yüksek tavan ve 400 kişide bile soğuk durmayan bir atmosfer. Fotoğraf açısından ahşap avantaj – flaş ışığı beyaz salonlardaki gibi düz kalmıyor, sıcak bir renk alıyor.","Ama asıl kozu dışarıda: Kappelberg bağları beş dakika yürüme mesafesinde. Altın saati kullanan çift, düğünden yarım saatten fazla ayrılmadan Toskana havasında portreler alıyor.","Akış için önerimiz: girişi çok geç saate koymayın. Salon pencerelerinden gün ışığı hâlâ giriyorsa, sadece yapay ışığa göre çok daha canlı kareler çıkıyor."],"en":["The Alte Kelter is one of the most popular wedding venues in the Rems-Murr district: massive wooden beams, high ceilings and a sense of space that does not feel cold even with 400 guests. Photographically the wood is an advantage – flash takes on a warm, pleasant colour here instead of falling flat as it does in white halls.","The biggest asset, though, is outside: the vine slopes on the Kappelberg are five minutes away on foot. Use the golden hour and you get portraits that look like Tuscany – without leaving the celebration for more than half an hour.","For the running order we recommend not putting the entrance too late. While the daylight through the hall windows is still playing along, the pictures come out considerably more alive than under artificial light alone."]},"city":"Fellbach","lead":{"de":"Hochzeitsfotograf für die Alte Kelter in Fellbach – warmes Holz, große Feiern und Weinberge fünf Minuten entfernt.","tr":"Fellbach Alte Kelter için düğün fotoğrafçısı – sıcak ahşap, büyük düğünler ve beş dakika ötede bağlar.","en":"Wedding photographer for the Alte Kelter in Fellbach – warm wood, large celebrations and vineyards five minutes away."},"name":"Alte Kelter Fellbach","slug":"alte-kelter-fellbach","type":{"de":"Festhalle / Kelter","tr":"Düğün salonu / şaraphane","en":"Festival hall / wine press house"},"light":{"de":"Warmes Holz reflektiert Blitzlicht angenehm. Tageslicht durch die Seitenfenster bis ca. eine Stunde vor Sonnenuntergang nutzbar.","tr":"Sıcak ahşap flaş ışığını hoş yansıtıyor. Yan pencerelerden gelen gün ışığı, gün batımından ~1 saat öncesine kadar kullanılabilir.","en":"Warm wood reflects flash pleasantly. Daylight through the side windows is usable until about an hour before sunset."},"rules":{"de":["Dekoaufnahmen nur im Zeitfenster vor dem Gästeeinlass möglich","Rauchmaschinen mit dem Hallenbetrieb abstimmen","Nachtaufnahmen draußen benötigen ein zusätzliches Dauerlicht – bringen wir mit"],"tr":["Süsleme çekimi yalnızca misafir girişinden önceki aralıkta mümkün","Sis makinesi için salon yönetimiyle görüşün","Dışarıda gece çekimi ek sürekli ışık gerektirir – biz getiriyoruz"],"en":["Décor shots are only possible in the slot before the guests are let in","Agree smoke machines with the hall management","Night shots outside need an additional continuous light – we bring one"]},"spots":{"de":["Rebhänge Kappelberg – goldene Stunde, 5 Gehminuten","Holzbalkenhalle im Gegenlicht der Seitenfenster","Innenhof / Vorplatz für Gruppenbilder","Weinberg-Treppen für Aufnahmen von oben"],"tr":["Kappelberg bağları – altın saat, 5 dakika yürüyüş","Yan pencerelerin kontra ışığında ahşap kirişli salon","Grup fotoğrafları için iç avlu / meydan","Yukarıdan çekimler için bağ merdivenleri"],"en":["Kappelberg vine slopes – golden hour, 5 minutes on foot","Timber-beamed hall backlit by the side windows","Courtyard / forecourt for group pictures","Vineyard steps for pictures from above"]},"timing":[{"time":"15:00","what":{"de":"Dekoaufnahmen im leeren Saal – vor dem Einlass","tr":"Boş salonda süsleme çekimi – misafir girişinden önce","en":"Décor shots in the empty hall – before doors open"}},{"time":"17:00","what":{"de":"Empfang draußen, Reportage der Begrüßung","tr":"Dışarıda karşılama, belgesel çekim","en":"Reception outside, reportage of the welcome"}},{"time":"19:30","what":{"de":"Paarshooting Rebhänge Kappelberg (30 Min.)","tr":"Kappelberg bağlarında çift çekimi (30 dk)","en":"Couple shoot on the Kappelberg vine slopes (30 min.)"}},{"time":"20:30","what":{"de":"Einzug, Tanz, Programm mit entfesseltem Licht","tr":"Giriş, dans, harici ışıkla program","en":"Entrance, dance, programme with off-camera light"}}],"address":"Kelterweg 1, 70734 Fellbach","capacity":{"de":"bis ca. 500 Gäste","tr":"yaklaşık 500 kişiye kadar","en":"up to about 500 guests"},"citySlug":"stuttgart"},{"faq":[{"a":{"de":"Ja. Innenhof und Arkaden bieten genügend geschützte Flächen, in denen wir auch bei Regen saubere Portraits machen können.","tr":"Evet. İç avlu ve revaklar, yağmurda da temiz portre çekebileceğimiz yeterli korunaklı alan sunuyor.","en":"Yes. The courtyard and the arcades offer enough sheltered space for us to make clean portraits even in rain."},"q":{"de":"Ist Schloss Hohenheim auch bei Regen eine gute Wahl?","tr":"Yağmurlu havada Schloss Hohenheim iyi bir tercih mi?","en":"Is Schloss Hohenheim a good choice in the rain too?"}}],"body":{"de":["Schloss Hohenheim ist die ruhige Alternative zu den großen Schlossanlagen. Die helle Fassade wirft weiches Reflexlicht auf das Brautpaar, der Park liefert Schatten, wenn die Sonne zu hart steht, und der Exotische Garten gibt Bilder, die man nicht sofort einer Region zuordnet.","Weil das Gelände zur Universität gehört, ist es an Wochenenden angenehm leer. Für Hochzeiten mit kleiner Gästezahl ist das ideal: keine Wartezeiten, keine Zuschauer, kurze Wege zwischen Trauort, Empfang und Portraits."],"tr":["Schloss Hohenheim, büyük saray komplekslerinin sakin alternatifi. Aydınlık cephe çifte yumuşak yansıma ışığı veriyor, park güneş sertleştiğinde gölge sunuyor ve Egzotik Bahçe, hangi bölgeye ait olduğu hemen anlaşılmayan kareler çıkarıyor.","Alan üniversiteye ait olduğu için hafta sonları oldukça boş. Küçük davetli sayılı düğünler için ideal: bekleme yok, izleyici yok, nikah–karşılama–portre arası mesafeler kısa."],"en":["Schloss Hohenheim is the quiet alternative to the large palace complexes. The bright façade throws soft reflected light onto the couple, the park provides shade when the sun stands too hard, and the Exotic Garden gives pictures you cannot immediately place in a region.","Because the grounds belong to the university, they are pleasantly empty at weekends. For weddings with a small guest list that is ideal: no waiting, no onlookers, short distances between the ceremony, the reception and the portraits."]},"city":"Stuttgart-Hohenheim","lead":{"de":"Hochzeitsfotograf für Schloss Hohenheim – heller Klassizismus, ein weitläufiger Park und viel Grün für Portraits.","tr":"Schloss Hohenheim için düğün fotoğrafçısı – aydınlık neoklasik mimari, geniş bir park ve portreler için bol yeşil.","en":"Wedding photographer for Schloss Hohenheim – bright neoclassicism, a wide park and plenty of green for portraits."},"name":"Schloss Hohenheim","slug":"schloss-hohenheim","type":{"de":"Schloss","tr":"Saray","en":"Palace"},"light":{"de":"Helle Fassade als natürlicher Reflektor. Park mit gleichmäßigem Schattenlicht auch mittags.","tr":"Aydınlık cephe doğal reflektör görevi görüyor. Park öğlen bile dengeli gölge ışığı veriyor.","en":"The bright façade works as a natural reflector. The park gives even shaded light at midday too."},"rules":{"de":["Universitätsgelände – Termine am Wochenende sind deutlich ruhiger","Gewerbliche Aufnahmen im Park vorab anmelden"],"tr":["Üniversite alanı – hafta sonu randevuları çok daha sakin","Parkta ticari çekim için önceden bildirim gerekli"],"en":["University grounds – dates at the weekend are considerably quieter","Register commercial photography in the park in advance"]},"spots":{"de":["Hauptfassade – heller Reflektor, ideal für Gruppenbilder","Exotischer Garten – ungewöhnliches Grün","Landesarboretum – alte Baumbestände, weiches Licht","Innenhof – geschützt bei Regen"],"tr":["Ana cephe – aydınlık reflektör, grup fotoğrafı için ideal","Egzotik Bahçe – alışılmadık bir yeşil","Arboretum – yaşlı ağaçlar, yumuşak ışık","İç avlu – yağmurda korunaklı"],"en":["Main façade – a bright reflector, ideal for group pictures","Exotic Garden – unusual greenery","State arboretum – old trees, soft light","Courtyard – sheltered in rain"]},"timing":[{"time":"12:00","what":{"de":"Trauung – ruhiger Rahmen, verfügbares Licht","tr":"Nikah – sakin ortam, mevcut ışık","en":"Ceremony – a calm setting, available light"}},{"time":"13:00","what":{"de":"Gratulation und Gruppenbilder vor der Fassade","tr":"Tebrikler ve cephe önünde grup fotoğrafları","en":"Congratulations and group pictures in front of the façade"}},{"time":"14:30","what":{"de":"Portraits im Park und im Exotischen Garten","tr":"Parkta ve Egzotik Bahçe\'de portreler","en":"Portraits in the park and the Exotic Garden"}},{"time":"17:00","what":{"de":"Feier – Reportage bis zum ersten Tanz","tr":"Düğün – ilk dansa kadar belgesel çekim","en":"Celebration – reportage up to the first dance"}}],"address":"Schloss Hohenheim, 70599 Stuttgart","capacity":{"de":"bis ca. 150 Gäste","tr":"yaklaşık 150 kişiye kadar","en":"up to about 150 guests"},"citySlug":"stuttgart"},{"faq":[{"a":{"de":"Ja, wenn die Location stimmt. Wir arbeiten mit klaren Ansagen statt endlosem Posieren – 30 Minuten ergeben in der Regel 40 bis 60 fertige Bilder.","tr":"Mekân doğruysa evet. Bitmeyen poz yerine net yönlendirmelerle çalışıyoruz – 30 dakika genelde 40–60 bitmiş kare veriyor.","en":"Yes, if the location is right. We work with clear direction instead of endless posing – 30 minutes usually gives 40 to 60 finished pictures."},"q":{"de":"Reichen 30 Minuten für ein Paarshooting wirklich?","tr":"Çift çekimi için 30 dakika gerçekten yeter mi?","en":"Is 30 minutes really enough for a couple shoot?"}}],"body":{"de":["Der Park an der Villa Berg ist unser Favorit für kurze Shootings mitten in Stuttgart. Wer im Rathaus heiratet, ist in zehn Minuten hier – und steht plötzlich zwischen alten Bäumen statt in der Innenstadt.","Für Paare mit engem Zeitplan bedeutet das: 30 Minuten reichen für eine komplette Portraitserie. Kein Umziehen, kein langes Fahren, keine Parkplatzsuche."],"tr":["Villa Berg parkı, Stuttgart\'ın göbeğinde kısa çekimler için favorimiz. Belediyede nikah kıyan çift on dakikada burada – ve birden şehir merkezi yerine yaşlı ağaçların arasında.","Programı sıkışık çiftler için bu şu demek: 30 dakika tam bir portre serisine yetiyor. Kıyafet değişimi yok, uzun yol yok, park yeri derdi yok."],"en":["The park at the Villa Berg is our favourite for short shoots in the middle of Stuttgart. Couples marrying at the town hall are here in ten minutes – and suddenly stand among old trees instead of in the city centre.","For couples with a tight schedule that means: 30 minutes is enough for a complete portrait series. No changing, no long drive, no hunting for a parking space."]},"city":"Stuttgart-Ost","lead":{"de":"Hochzeitsfotograf rund um die Villa Berg in Stuttgart-Ost – urbaner Park, ruhige Wege, ideal für Paarshootings zwischen Standesamt und Feier.","tr":"Stuttgart-Ost\'ta Villa Berg çevresinde düğün fotoğrafçısı – şehir içinde park, sakin yollar; nikah ile düğün arasındaki çift çekimi için ideal.","en":"Wedding photographer around the Villa Berg in Stuttgart-Ost – an urban park, quiet paths, ideal for couple shoots between the registry office and the celebration."},"name":"Villa Berg & Umgebung","slug":"villa-berg","type":{"de":"Villa / Park","tr":"Villa / park","en":"Villa / park"},"light":{"de":"Alter Baumbestand streut das Licht. Auch mittags nutzbar – im Gegensatz zu offenen Plätzen in der Innenstadt.","tr":"Yaşlı ağaçlar ışığı yayıyor. Şehir merkezindeki açık meydanların aksine öğlen de kullanılabilir.","en":"Old trees scatter the light. Usable at midday too – unlike the open squares in the city centre."},"rules":{"de":["Öffentlicher Park – bitte Rücksicht auf Besucher nehmen","Kein Aufbau von großen Lichtstativen auf den Hauptwegen"],"tr":["Halka açık park – ziyaretçilere dikkat","Ana yollarda büyük ışık ayakları kurulmuyor"],"en":["A public park – please be considerate of other visitors","No setting up large light stands on the main paths"]},"spots":{"de":["Alleen im Park – lange Fluchten","Treppenanlagen – Höhe und Struktur im Bild","Wiesenflächen – weiches Gegenlicht am Nachmittag"],"tr":["Park içindeki ağaçlı yollar – uzun perspektif","Merdivenler – kadrajda kot farkı ve doku","Çayırlar – öğleden sonra yumuşak kontra ışık"],"en":["Avenues in the park – long lines of sight","Flights of steps – height and structure in the frame","Open meadows – soft backlight in the afternoon"]},"timing":[{"time":"10:30","what":{"de":"Trauung im Standesamt Stuttgart","tr":"Stuttgart nikah dairesinde tören","en":"Ceremony at the Stuttgart registry office"}},{"time":"11:30","what":{"de":"Fahrt zum Park (10 Min.)","tr":"Parka geçiş (10 dk)","en":"Drive to the park (10 min.)"}},{"time":"11:45","what":{"de":"Paarshooting im Park – 30 Minuten","tr":"Parkta çift çekimi – 30 dakika","en":"Couple shoot in the park – 30 minutes"}},{"time":"13:00","what":{"de":"Weiterfahrt zur Feier","tr":"Düğün mekânına hareket","en":"On to the celebration"}}],"address":"Villa Berg, 70190 Stuttgart","capacity":{"de":"kleine bis mittlere Feiern","tr":"küçük ve orta ölçekli kutlamalar","en":"small to medium celebrations"},"citySlug":"stuttgart"},{"faq":[{"a":{"de":"Immer vor dem Gästeeinlass. Sobald die Halle voll ist, sind saubere Übersichtsbilder der Dekoration praktisch nicht mehr möglich.","tr":"Her zaman misafirler girmeden önce. Salon dolduktan sonra süslemenin temiz genel karesi pratikte mümkün olmuyor.","en":"Always before the guests are let in. Once the hall is full, clean overall pictures of the décor are practically impossible."},"q":{"de":"Wann sollten die Dekoaufnahmen entstehen?","tr":"Süsleme çekimleri ne zaman yapılmalı?","en":"When should the décor shots be taken?"}}],"body":{"de":["Die Filderhalle ist eine der meistgebuchten Hallen im Süden Stuttgarts – gute Autobahnanbindung, Parkplätze direkt am Haus und ein Saal, der sich flexibel bestuhlen lässt. Fotografisch ist sie ein klassischer Fall: neutraler Raum, viel Kunstlicht, das Bild entsteht durch Menschen und Licht, nicht durch die Architektur.","Deshalb legen wir hier besonderen Wert auf die Dekoaufnahmen vor dem Einlass und auf ein sauberes Blitzsetup für Einzug und Bühne. Für Portraits fahren wir mit dem Paar zehn Minuten Richtung Felder – dort entsteht der Kontrast zur Halle."],"tr":["Filderhalle, Stuttgart\'ın güneyinde en çok tercih edilen salonlardan biri – otoyola yakın, kapıda otopark ve esnek oturma düzeni. Fotoğraf açısından klasik bir durum: nötr mekân, bol yapay ışık; kareyi mimari değil insanlar ve ışık kuruyor.","Bu yüzden burada giriş öncesi süsleme çekimine ve giriş/sahne için temiz bir flaş kurulumuna özellikle önem veriyoruz. Portreler için çiftle on dakika tarlalara doğru çıkıyoruz – salona kontrast orada oluşuyor."],"en":["The Filderhalle is one of the most booked halls in the south of Stuttgart – good motorway access, parking right by the building and a hall that can be laid out flexibly. Photographically it is a classic case: a neutral room, a lot of artificial light, and the picture comes from people and light rather than from the architecture.","That is why we put particular weight here on the décor shots before doors open and on a clean flash setup for the entrance and the stage. For portraits we drive ten minutes with the couple towards the fields – that is where the contrast to the hall comes from."]},"city":"Leinfelden-Echterdingen","lead":{"de":"Hochzeitsfotograf & Videograf für die Filderhalle in Leinfelden-Echterdingen – große Feiern, klare Reportage, planbarer Ablauf.","tr":"Leinfelden-Echterdingen Filderhalle için düğün fotoğrafçısı ve videografı – büyük düğünler, net belgesel çekim, planlanabilir akış.","en":"Wedding photographer & videographer for the Filderhalle in Leinfelden-Echterdingen – large celebrations, clear reportage, a running order you can plan."},"name":"Filderhalle Leinfelden","slug":"filderhalle-leinfelden","type":{"de":"Festhalle / Eventlocation","tr":"Düğün salonu / etkinlik mekânı","en":"Festival hall / event venue"},"light":{"de":"Neutrales Hallenlicht. Wir setzen zwei entfesselte Blitze und nutzen Tageslicht durch das Foyer, solange es geht.","tr":"Nötr salon ışığı. İki harici flaş kuruyor, mümkün olduğunca fuayedeki gün ışığını kullanıyoruz.","en":"Neutral hall light. We set up two off-camera flashes and use daylight through the foyer for as long as it lasts."},"rules":{"de":["Zeitfenster für Dekoaufnahmen mit dem Veranstalter fest einplanen","Technik-Absprache wegen Bühnenlicht empfohlen"],"tr":["Süsleme çekimi için organizatörle net bir saat belirleyin","Sahne ışığı için teknik ekiple görüşülmesi önerilir"],"en":["Fix the slot for décor shots with the organiser in advance","A word with the technicians about stage lighting is recommended"]},"spots":{"de":["Foyer mit Glasfront – natürliches Licht für Empfangsbilder","Felder und Alleen Richtung Echterdingen – 10 Minuten Fahrt","Haupteingang bei Nacht – Dauerlicht für Gruppenaufnahmen"],"tr":["Cam cepheli fuaye – karşılama kareleri için doğal ışık","Echterdingen yönündeki tarlalar ve ağaçlı yollar – 10 dakika","Gece ana giriş – grup çekimleri için sürekli ışık"],"en":["Foyer with a glass front – natural light for reception pictures","Fields and avenues towards Echterdingen – a 10-minute drive","Main entrance at night – continuous light for group shots"]},"timing":[{"time":"16:00","what":{"de":"Saal- und Dekoaufnahmen vor dem Einlass","tr":"Giriş öncesi salon ve süsleme çekimi","en":"Hall and décor shots before doors open"}},{"time":"17:30","what":{"de":"Empfang im Foyer – Tageslicht","tr":"Fuayede karşılama – gün ışığı","en":"Reception in the foyer – daylight"}},{"time":"19:00","what":{"de":"Paarshooting draußen, 20 Minuten","tr":"Dışarıda çift çekimi, 20 dakika","en":"Couple shoot outside, 20 minutes"}},{"time":"20:00","what":{"de":"Einzug & Programm mit Blitzsetup","tr":"Giriş ve program, flaş kurulumuyla","en":"Entrance & programme with the flash setup"}}],"address":"Bahnhofstraße 61, 70771 Leinfelden-Echterdingen","capacity":{"de":"bis ca. 600 Gäste","tr":"yaklaşık 600 kişiye kadar","en":"up to about 600 guests"},"citySlug":"stuttgart"},{"slug":"imza","name":"imza","city":"thannhausen","citySlug":"guenzburg","address":"im krautgarten","type":{"de":"","tr":""},"capacity":{"de":"","tr":""},"lead":{"de":"","tr":""},"body":{"de":[],"tr":[]},"light":{"de":"","tr":""},"rules":{"de":[],"tr":[]},"spots":{"de":[],"tr":[]},"timing":[],"faq":[],"lat":"","lng":""}],"contact":{"zip":"86381","city":"Krumbach (Schwaben)","email":"hallo@han-studio.de","hours":{"de":"Mo–Fr 10:00–18:00 · Sa nach Vereinbarung","tr":"Pzt–Cu 10:00–18:00 · Cmt randevuyla","en":"Mon–Fri 10:00–18:00 · Sat by arrangement"},"phone":"","street":"","instagram":"https://instagram.com/","mapsQuery":"","phoneHuman":""},"process":[{"step":"01","text":{"de":"Ein Gespräch per Video oder im Atelier. Ihr erzählt vom Tag, wir sagen ehrlich, was zeitlich realistisch ist.","tr":"Video ile ya da atölyede bir görüşme. Siz günü anlatıyorsunuz, biz zaman açısından neyin gerçekçi olduğunu açıkça söylüyoruz.","en":"A conversation by video or at the studio. You tell us about the day, we say honestly what is realistic in the time."},"title":{"de":"Kennenlernen","tr":"Tanışma","en":"Getting to know each other"}},{"step":"02","text":{"de":"Vier Wochen vorher erstellen wir gemeinsam einen Ablaufplan – inklusive Lichtzeiten und Puffer für die Location.","tr":"Dört hafta önce birlikte bir akış planı çıkarıyoruz – ışık saatleri ve mekân için zaman payı dahil.","en":"Four weeks beforehand we build a running order together – including the hours of good light and some slack for the venue."},"title":{"de":"Zeitplan","tr":"Zaman planı","en":"The timeline"}},{"step":"03","text":{"de":"Wir sind da, bevor es losgeht, und bleiben, bis die Party läuft. Ohne Kommandos, ohne Unterbrechung.","tr":"Başlamadan önce oradayız ve parti oturana kadar kalıyoruz. Komut yok, kesinti yok.","en":"We are there before it starts and stay until the party is running. No commands, no interruptions."},"title":{"de":"Der Tag","tr":"Düğün günü","en":"The day"}},{"step":"04","text":{"de":"Nach drei Wochen bekommt ihr eure private Galerie. Dort markiert ihr per Herz die Bilder fürs Album – wir sehen die Auswahl direkt.","tr":"Üç hafta sonra özel galeriniz hazır. Albüm için kareleri kalp ile işaretliyorsunuz – seçiminizi anında görüyoruz.","en":"After three weeks you get your private gallery. There you mark the album pictures with a heart – we see the selection immediately."},"title":{"de":"Galerie & Auswahl","tr":"Galeri & seçim","en":"Gallery & selection"}}],"stories":[{"body":{"de":["Elif und Marco wollten zwei Traditionen in einen Tag bringen, ohne dass sich eine davon wie ein Programmpunkt anfühlt. Der Morgen gehörte der Familie, der Nachmittag der Trauung im Weißen Saal, der Abend dem Fest.","Für uns war das ein Tag mit vielen kleinen Übergängen – und genau die machen so eine Reportage aus. Das schönste Bild entstand nicht beim Shooting, sondern als Elifs Großmutter ihr kurz vor dem Einzug die Hand hielt."],"tr":["Elif ve Marco iki geleneği tek güne sığdırmak istiyordu, ama hiçbiri program maddesi gibi durmasın diye. Sabah aileye, öğleden sonra Beyaz Salon\'daki nikaha, akşam da düğüne ayrıldı.","Bizim için bu, çok sayıda küçük geçişin olduğu bir gündü – ve böyle bir çekimi asıl bunlar oluşturur. En güzel kare çekim sırasında değil, girişten hemen önce Elif\'in babaannesi elini tuttuğunda çıktı."],"en":["Elif and Marco wanted to bring two traditions into one day without either of them feeling like an item on a programme. The morning belonged to the family, the afternoon to the ceremony in the White Hall, the evening to the celebration.","For us it was a day of many small transitions – and those are exactly what make a reportage like this. The best picture did not come from the shoot but from the moment Elif\'s grandmother held her hand just before the entrance."]},"slug":"elif-marco-schloss-solitude","intro":{"de":"Eine deutsch-türkische Hochzeit auf Schloss Solitude – mit Sonnenuntergang auf der Sichtachse und Feier bis halb zwei.","tr":"Schloss Solitude\'da Türk-Alman düğünü – eksende gün batımı ve gece bir buçuğa kadar kutlama.","en":"A German-Turkish wedding at Schloss Solitude – with sunset along the sightline and a celebration until half past one."},"month":{"de":"Juni","tr":"Haziran","en":"June"},"quote":{"de":"Wir haben euch den ganzen Tag kaum gesehen – und trotzdem ist alles auf den Bildern.","tr":"Sizi gün boyu neredeyse hiç görmedik – ama her şey karelerde var.","en":"We barely saw you all day – and still everything is there in the pictures."},"seeds":["story-elif-1","story-elif-2","story-elif-3","story-elif-4","story-elif-5","story-elif-6"],"venue":{"de":"Schloss Solitude, Stuttgart","tr":"Schloss Solitude, Stuttgart","en":"Schloss Solitude, Stuttgart"},"couple":"Elif & Marco","guests":"120","citySlug":"stuttgart","venueSlug":"schloss-solitude","uploads":[]},{"body":{"de":["Bei 260 Gästen bleibt selten Zeit für Portraits. Wir haben deshalb im Vorgespräch ein festes Fenster vereinbart: 19:30 Uhr, 30 Minuten, Rebhänge. Der Rest des Abends gehörte der Reportage.","Die Bilder aus dieser halben Stunde sind die, die heute im Wohnzimmer hängen – und trotzdem hat niemand gemerkt, dass das Brautpaar kurz weg war."],"tr":["260 kişide portreye nadiren zaman kalır. Bu yüzden ön görüşmede sabit bir aralık belirledik: 19:30, 30 dakika, bağlar. Akşamın kalanı belgesel çekime kaldı.","Bugün oturma odasında asılı olan kareler o yarım saatten – yine de kimse çiftin kısa süre ayrıldığını fark etmedi."],"en":["With 260 guests there is rarely time for portraits. So in the first conversation we agreed a fixed window: 7:30 pm, 30 minutes, the vine slopes. The rest of the evening belonged to the reportage.","The pictures from that half hour are the ones hanging in the living room today – and still nobody noticed the couple had been away."]},"slug":"sarah-daniel-alte-kelter","intro":{"de":"Weinberge, warmes Holz und eine Feier, die um 19:30 Uhr für 30 Minuten in den Kappelberg ausgewichen ist.","tr":"Bağlar, sıcak ahşap ve 19:30\'da otuz dakikalığına Kappelberg\'e çıkan bir düğün.","en":"Vineyards, warm wood and a celebration that slipped up to the Kappelberg for 30 minutes at 7:30 pm."},"month":{"de":"September","tr":"Eylül","en":"September"},"quote":{"de":"Die halbe Stunde in den Weinbergen war die beste Entscheidung des Tages.","tr":"Bağlardaki o yarım saat günün en iyi kararıydı.","en":"The half hour in the vineyards was the best decision of the day."},"seeds":["story-sarah-1","story-sarah-2","story-sarah-3","story-sarah-4","story-sarah-5","story-sarah-6"],"venue":{"de":"Alte Kelter, Fellbach","tr":"Alte Kelter, Fellbach","en":"Alte Kelter, Fellbach"},"couple":"Sarah & Daniel","guests":"260","citySlug":"stuttgart","venueSlug":"alte-kelter-fellbach"},{"body":{"de":["Große Hallen sind eine Lichtfrage. Wir haben zwei Blitzstative gesetzt, das Video-Team hat mit Gimbal gearbeitet, und der Einzug wurde aus zwei Perspektiven gleichzeitig aufgenommen.","Für das Paarshooting sind wir um 16:00 Uhr raus, bevor die Gäste kamen – 25 Minuten, die den Unterschied gemacht haben."],"tr":["Büyük salonlar bir ışık meselesidir. İki flaş ayağı kurduk, video ekibi gimbal ile çalıştı ve giriş aynı anda iki açıdan kaydedildi.","Çift çekimi için misafirler gelmeden 16:00\'da dışarı çıktık – farkı yaratan 25 dakika."],"en":["Large halls are a question of light. We set two flash stands, the video team worked with a gimbal, and the entrance was recorded from two perspectives at once.","For the couple shoot we went outside at 4 pm, before the guests arrived – 25 minutes that made the difference."]},"slug":"aylin-emre-si-centrum","intro":{"de":"600 Gäste, Bühnenprogramm, Konfetti – eine große Feier, die trotzdem ruhige Bilder zulässt.","tr":"600 kişi, sahne programı, konfeti – buna rağmen sakin kareler veren büyük bir düğün.","en":"600 guests, a stage programme, confetti – a large celebration that still leaves room for quiet pictures."},"month":{"de":"August","tr":"Ağustos","en":"August"},"quote":{"de":"Wir hatten Angst, dass die Bilder im dunklen Saal nichts werden. Das Gegenteil ist passiert.","tr":"Karanlık salonda kareler olmaz diye korkuyorduk. Tam tersi oldu.","en":"We were afraid the pictures in the dark hall would come to nothing. The opposite happened."},"seeds":["story-aylin-1","story-aylin-2","story-aylin-3","story-aylin-4","story-aylin-5","story-aylin-6"],"venue":{"de":"SI-Centrum, Stuttgart","tr":"SI-Centrum, Stuttgart","en":"SI-Centrum, Stuttgart"},"couple":"Aylin & Emre","guests":"600","citySlug":"stuttgart","venueSlug":"si-centrum-stuttgart"},{"body":{"de":["Lena und Jonas hatten eine klare Vorstellung: wenig Inszenierung, viel Familie. Wir haben den Tag entsprechend leicht gehalten und nur zwei feste Blöcke gesetzt – das Shooting im Park und die blaue Stunde.","Die Genehmigung für das Blühende Barock haben wir vier Wochen vorher beantragt. Das ist der Punkt, an dem Erfahrung Zeit spart."],"tr":["Lena ve Jonas\'ın net bir isteği vardı: az kurgu, çok aile. Günü buna göre hafif tuttuk ve sadece iki sabit blok koyduk – parktaki çekim ve mavi saat.","Blühendes Barock iznini dört hafta önceden aldık. Tecrübenin zaman kazandırdığı nokta tam burası."],"en":["Lena and Jonas had a clear idea: little staging, a lot of family. We kept the day light accordingly and set only two fixed blocks – the shoot in the park and the blue hour.","We applied for the permit for the Blühendes Barock four weeks beforehand. That is the point where experience saves time."]},"slug":"lena-jonas-residenzschloss","intro":{"de":"Barocke Innenhöfe, ein Shooting im Blühenden Barock und zehn Minuten blaue Stunde an der Fassade.","tr":"Barok iç avlular, Blühendes Barock\'ta çekim ve cephede on dakikalık mavi saat.","en":"Baroque courtyards, a shoot in the Blühendes Barock and ten minutes of blue hour at the façade."},"month":{"de":"Mai","tr":"Mayıs","en":"May"},"quote":{"de":"Ihr habt den Zeitplan gerettet, bevor wir überhaupt gemerkt haben, dass es einen gibt.","tr":"Bir program olduğunu biz fark etmeden siz o programı kurtardınız.","en":"You rescued the timeline before we had even noticed there was one."},"seeds":["story-lena-1","story-lena-2","story-lena-3","story-lena-4","story-lena-5","story-lena-6"],"venue":{"de":"Residenzschloss, Ludwigsburg","tr":"Residenzschloss, Ludwigsburg","en":"Residenzschloss, Ludwigsburg"},"couple":"Lena & Jonas","guests":"90","citySlug":"stuttgart","venueSlug":"residenzschloss-ludwigsburg"},{"slug":"gamze-yusuf","couple":"Gamze&Yusuf","guests":"","citySlug":"stuttgart","venueSlug":"","venue":{"de":"","tr":""},"month":{"de":"","tr":""},"intro":{"de":"test einleitung","tr":"einleitung türkce","en":"test intro"},"body":{"de":["text test"],"tr":[],"en":["test text"]},"quote":{"de":"","tr":""},"seeds":["story-gamze-yusuf-1","story-gamze-yusuf-2","story-gamze-yusuf-3","story-gamze-yusuf-4","story-gamze-yusuf-5","story-gamze-yusuf-6"],"uploads":["/uploads/stories/gamze-yusuf/19c7918783135734.jpg","/uploads/stories/gamze-yusuf/e36a9e755eec2f44.jpg","/uploads/stories/gamze-yusuf/d3e1fe7bda44fecf.jpg"],"videoUrl":"https://youtu.be/f3bbGDxvGAM?si=MbliuGC16kzYdUFg"}],"campaign":{"code":"lumiere2026","active":true},"packages":[{"hint":{"de":"4 Stunden Begleitung","tr":"4 saat çekim","en":"4 hours with you"},"name":{"de":"Standesamt & Feier","tr":"Nikah & Kutlama","en":"Registry office & celebration"},"slug":"standesamt","price":"690 €","features":{"de":["4 Stunden Fotoreportage","ca. 150 bearbeitete Bilder","Private Online-Galerie, 12 Monate online","Download in voller Auflösung","Lieferung in 10 Werktagen"],"tr":["4 saat fotoğraf çekimi","yaklaşık 150 düzenlenmiş kare","Özel online galeri, 12 ay erişim","Tam çözünürlük indirme","10 iş gününde teslim"],"en":["4 hours of photo coverage","around 150 edited pictures","Private online gallery, online for 12 months","Download in full resolution","Delivered within 10 working days"]},"featured":false},{"hint":{"de":"10 Stunden, Getting Ready bis Party","tr":"10 saat, hazırlıktan partiye","en":"10 hours, getting ready to party"},"name":{"de":"Der ganze Tag","tr":"Tüm Gün","en":"The whole day"},"slug":"klassik","price":"1.890 €","featured":true,"features":{"de":["10 Stunden Fotoreportage","Zweiter Fotograf ab 150 Gästen","400–600 bearbeitete Bilder","Paarshooting zur goldenen Stunde","Private Online-Galerie mit Foto-Auswahl fürs Album","Digitale Hochzeitseinladung gratis","Lieferung in 3 Wochen"],"tr":["10 saat fotoğraf çekimi","150 kişiden itibaren ikinci fotoğrafçı","400–600 düzenlenmiş kare","Altın saatte çift çekimi","Albüm seçimi yapılabilen özel online galeri","Dijital düğün davetiyesi ücretsiz","3 haftada teslim"],"en":["10 hours of photo coverage","Second photographer from 150 guests","400–600 edited pictures","Couple shoot in the golden hour","Private online gallery with album selection","Digital wedding invitation free of charge","Delivered within 3 weeks"]}},{"hint":{"de":"Team aus 2 Personen, ganzer Tag","tr":"2 kişilik ekip, tüm gün","en":"Team of two, the whole day"},"name":{"de":"Foto & Film","tr":"Foto & Film","en":"Photo & film"},"slug":"foto-video","price":"3.490 €","features":{"de":["Alles aus „Der ganze Tag“","Highlight-Film 4–6 Minuten in 4K","Funkmikrofone für Trauung & Reden","Vertikale Social-Version","Ungeschnittener Mitschnitt der Trauung","Digitale Hochzeitseinladung gratis","Lieferung Film in 6 Wochen"],"tr":["„Tüm Gün“ paketindeki her şey","4K\'da 4–6 dakikalık highlight film","Nikah ve konuşmalar için telsiz mikrofon","Sosyal medya için dikey versiyon","Nikahın kesilmemiş kaydı","Dijital düğün davetiyesi ücretsiz","Film teslimi 6 hafta"],"en":["Everything from „The whole day“","Highlight film of 4–6 minutes in 4K","Radio microphones for the ceremony & speeches","Vertical version for social media","Uncut recording of the ceremony","Digital wedding invitation free of charge","Film delivered within 6 weeks"]},"featured":false}],"services":[{"body":{"de":["Unsere Reportagen leben von echten Momenten: der Blick der Mutter beim Ankleiden, die zitternden Hände beim Ringtausch, der Vater, der sich beim ersten Tanz wegdreht. Dafür arbeiten wir leise, mit zwei Kameras und ohne den Tag zu unterbrechen.","Ein Paarshooting von 30 bis 45 Minuten planen wir trotzdem ein – nicht für gestellte Posen, sondern für die zwei, drei ruhigen Bilder, die später über dem Sofa hängen."],"tr":["Çekimlerimiz gerçek anlardan besleniyor: gelin hazırlanırken annenin bakışı, yüzük takılırken titreyen eller, ilk dansta başını çeviren baba. Bunun için sessiz çalışıyor, iki gövde kullanıyor ve günü bölmüyoruz.","Yine de 30–45 dakikalık bir çift çekimi planlıyoruz – kurgulu pozlar için değil, sonradan duvara asılacak o iki üç sakin kare için."],"en":["Our reportage lives on real moments: the mother\'s look while the dress goes on, the shaking hands at the exchange of rings, the father who turns away during the first dance. For that we work quietly, with two cameras, and without interrupting the day.","We still plan a couple shoot of 30 to 45 minutes – not for staged poses, but for the two or three quiet pictures that later hang above the sofa."]},"seed":"lum-service-foto","slug":"hochzeitsfotografie","short":{"de":"Dokumentarisch, ruhig, ohne stundenlanges Posieren. Wir halten fest, was ohnehin passiert.","tr":"Belgesel tarzda, sakin, saatlerce poz vermeden. Zaten yaşananı kayda alıyoruz.","en":"Documentary, quiet, without hours of posing. We hold on to what happens anyway."},"title":{"de":"Hochzeitsfotografie","tr":"Düğün Fotoğrafçılığı","en":"Wedding photography"},"bullets":{"de":["Zwei Fotografen bei Feiern ab 150 Gästen","Vollformat-Technik, lichtstarke Festbrennweiten","Farb- und Schwarzweiß-Bearbeitung von Hand","Online-Galerie mit Download in voller Auflösung"],"tr":["150 kişiden büyük düğünlerde iki fotoğrafçı","Full frame ekipman, geniş diyaframlı sabit lensler","Elde renk ve siyah-beyaz düzenleme","Tam çözünürlük indirmeli online galeri"],"en":["Two photographers for celebrations from 150 guests","Full-frame bodies, fast prime lenses","Colour and black-and-white editing by hand","Online gallery with full-resolution download"]}},{"body":{"de":["Der Highlight-Film dauert vier bis sechs Minuten. Er ist so geschnitten, dass er auch Gäste mitnimmt, die nicht dabei waren: die Rede des Vaters als Tonspur, der Einzug in Zeitlupe, das Lachen beim Anschneiden der Torte.","Auf Wunsch gibt es zusätzlich den ungeschnittenen Mitschnitt von Trauung und Reden – für die Familie oft das Wichtigste."],"tr":["Highlight film dört ila altı dakika. Orada olmayan misafirleri de içine alacak şekilde kurgulanıyor: ses olarak babanın konuşması, ağır çekimde giriş, pasta kesiminde kahkaha.","İsteğe bağlı olarak nikah ve konuşmaların kesilmemiş kaydı da veriliyor – aile için çoğu zaman en değerlisi bu."],"en":["The highlight film runs four to six minutes. It is cut so that it carries even the guests who were not there: the father\'s speech as the soundtrack, the entrance in slow motion, the laughter as the cake is cut.","On request there is also the uncut recording of the ceremony and the speeches – often the most important thing for the family."]},"seed":"lum-service-video","slug":"hochzeitsvideo","short":{"de":"Ein Film, den ihr wirklich anschaut – kurz, musikalisch, mit euren Stimmen.","tr":"Gerçekten izleyeceğiniz bir film – kısa, müzikli, kendi seslerinizle.","en":"A film you will actually watch – short, musical, with your own voices."},"title":{"de":"Hochzeitsfilm & Video","tr":"Düğün Filmi & Video","en":"Wedding film & video"},"bullets":{"de":["Highlight-Film 4–6 Minuten in 4K","Funkmikrofone für Reden und Zeremonie","Gimbal & Slider, keine hektischen Schnitte","Vertikale Version für Instagram inklusive"],"tr":["4K\'da 4–6 dakikalık highlight film","Konuşma ve tören için telsiz mikrofon","Gimbal ve slider, telaşlı kurgu yok","Instagram için dikey versiyon dahil"],"en":["Highlight film of 4–6 minutes in 4K","Radio microphones for speeches and ceremony","Gimbal & slider, no frantic cuts","Vertical version for Instagram included"]}},{"body":{"de":["Nicht jede Hochzeit dauert zwölf Stunden. Für standesamtliche Trauungen, Verlobungen und Henna-Abende gibt es kompakte Pakete ab zwei Stunden – mit derselben Technik und derselben Bildsprache wie bei den großen Feiern."],"tr":["Her düğün on iki saat sürmüyor. Resmi nikah, nişan ve kına geceleri için iki saatten başlayan kompakt paketler var – büyük düğünlerdeki aynı ekipman ve aynı görsel dille."],"en":["Not every wedding lasts twelve hours. For registry office ceremonies, engagements and henna nights there are compact packages from two hours – with the same equipment and the same visual language as the big celebrations."]},"seed":"lum-service-standesamt","slug":"standesamt","short":{"de":"Kompakte Begleitung für kleine Feiern, Verlobungen und Henna-Abende.","tr":"Küçük kutlamalar, nişan ve kına geceleri için kompakt çekim.","en":"Compact coverage for small celebrations, engagements and henna nights."},"title":{"de":"Standesamt & Verlobung","tr":"Nikah & Nişan","en":"Registry office & engagement"},"bullets":{"de":["Ab 2 Stunden buchbar","Ideal für Henna-Abend & Verlobung","Lieferung innerhalb von 10 Tagen","Aufstockung auf Tagespaket jederzeit möglich"],"tr":["2 saatten itibaren","Kına gecesi ve nişan için ideal","10 gün içinde teslim","İstediğiniz zaman tam gün pakete yükseltme"],"en":["Bookable from 2 hours","Ideal for henna night & engagement","Delivered within 10 days","Can be topped up to a full-day package at any time"]}},{"body":{"de":["Am Hochzeitstag ist selten Zeit für lange Portraits. Ein After-Wedding-Shooting löst das: zwei Stunden, ein Ort eurer Wahl – Weinberge, Schwarzwald, Bodensee oder eine Reise – und komplett ohne Zeitplan im Nacken."],"tr":["Düğün günü uzun portreler için nadiren zaman kalıyor. After-Wedding çekimi bunu çözüyor: iki saat, sizin seçtiğiniz bir yer – bağlar, Karaorman, Bodensee ya da bir seyahat – ve ensenizde program baskısı olmadan."],"en":["On the wedding day there is rarely time for long portraits. An after-wedding shoot solves that: two hours, a place of your choice – vineyards, the Black Forest, Lake Constance or a trip – and with no timetable breathing down your neck."]},"seed":"lum-service-after","slug":"after-wedding","short":{"de":"Noch einmal ins Kleid – ohne Zeitdruck, an einem Ort, den ihr euch aussucht.","tr":"Gelinliği bir kez daha giyin – zaman baskısı olmadan, seçtiğiniz bir yerde.","en":"Into the dress once more – no time pressure, in a place you choose yourselves."},"title":{"de":"After-Wedding & Paarshooting","tr":"After-Wedding & Çift Çekimi","en":"After-wedding & couple shoot"},"bullets":{"de":["2 Stunden reine Shootingzeit","Locationvorschläge inklusive","Auch als Reise-Shooting buchbar","40+ bearbeitete Bilder"],"tr":["2 saat net çekim","Mekân önerileri dahil","Seyahat çekimi olarak da mümkün","40+ düzenlenmiş kare"],"en":["2 hours of pure shooting time","Location suggestions included","Also bookable as a travel shoot","40+ edited pictures"]}}],"marketing":{"pages":{"agb":{"image":"","title":{"de":"","tr":""},"noindex":false,"description":{"de":"","tr":""}},"home":{"image":"","title":{"de":"Hochzeitsfotograf Krumbach – Foto & Video | Han Studio","tr":"Stuttgart Düğün Fotoğrafçısı – Foto & Video | Han Studio","en":"Wedding photographer Krumbach – photo & video | Han Studio"},"noindex":false,"description":{"de":"Dokumentarische Hochzeitsfotografie und Hochzeitsfilm in Krumbach, Günzburg, Ulm, Memmingen und Augsburg. Private Kundengalerie mit Album-Auswahl und digitale Hochzeitseinladung inklusive.","tr":"Stuttgart, Ludwigsburg, Esslingen ve çevresinde belgesel tarzda düğün fotoğrafçılığı ve düğün filmi. Albüm seçimli özel müşteri galerisi ve dijital düğün davetiyesi dahil.","en":"Documentary wedding photography and wedding film in Krumbach, Günzburg, Ulm, Memmingen and Augsburg. Private client gallery with album selection and a digital wedding invitation included."}},"preise":{"image":"","title":{"de":"Preise Hochzeitsfotograf Krumbach – ab 690 €","tr":"Stuttgart düğün fotoğrafçısı fiyatları – 690 €\'dan","en":"Prices wedding photographer Krumbach – from 690 €"},"noindex":false,"description":{"de":"Transparente Pakete: Standesamt ab 690 €, Ganztagesreportage ab 1.890 €, Foto & Film ab 3.490 €. Anfahrt bis 60 km inklusive.","tr":"Şeffaf paketler: nikah 690 €\'dan, tam gün çekim 1.890 €\'dan, foto & film 3.490 €\'dan. 60 km\'ye kadar ulaşım dahil.","en":"Clear packages: registry office from 690 €, full-day reportage from 1,890 €, photo & film from 3,490 €. Travel up to 60 km included."}},"galerie":{"image":"","title":{"de":"Kundengalerie – Login","tr":"Müşteri galerisi – giriş","en":"Client gallery – sign in"},"noindex":true,"description":{"de":"","tr":""}},"kontakt":{"image":"","title":{"de":"Kontakt – Hochzeitsfotograf Krumbach anfragen","tr":"İletişim – Stuttgart düğün fotoğrafçısı","en":"Contact – enquire with a wedding photographer in Krumbach"},"noindex":false,"description":{"de":"Fragt euer Hochzeitsdatum an. Antwort in der Regel innerhalb von 24 Stunden. Atelier in Krumbach (Schwaben).","tr":"Düğün tarihinizi sorun. Genelde 24 saat içinde yanıt. Atölye Stuttgart merkezde.","en":"Ask about your wedding date. Usually answered within 24 hours. Studio in Krumbach (Swabia)."}},"ratgeber":{"image":"","title":{"de":"Ratgeber – Hochzeitsfotografie, Zeitplan & Locations","tr":"Rehber – düğün fotoğrafçılığı, akış planı ve mekânlar","en":"Guide – wedding photography, timeline & venues"},"noindex":false,"description":{"de":"","tr":""}},"regionen":{"image":"","title":{"de":"Hochzeitsfotograf in Krumbach & Umgebung – alle Regionen","tr":"Stuttgart ve çevresinde düğün fotoğrafçısı – tüm bölgeler","en":"Wedding photographer in Krumbach & around – all regions"},"noindex":false,"description":{"de":"Günzburg, Ulm, Neu-Ulm, Memmingen, Augsburg, München und mehr: Hochzeitsfotograf und Videograf mit Ortskenntnis – Anfahrt bis 60 km inklusive.","tr":"Stuttgart, Ludwigsburg, Esslingen, Böblingen, Heilbronn, Tübingen ve daha fazlası: bölgeyi tanıyan düğün fotoğrafçısı ve videografı – 60 km\'ye kadar ulaşım dahil.","en":"Günzburg, Ulm, Neu-Ulm, Memmingen, Augsburg, Munich and more: wedding photographer and videographer who knows the ground – travel up to 60 km included."}},"einladung":{"image":"","title":{"de":"Digitale Hochzeitseinladung erstellen – mit RSVP & Countdown","tr":"Dijital düğün davetiyesi oluştur – RSVP ve geri sayımlı","en":"Create a digital wedding invitation – with RSVP & countdown"},"noindex":false,"description":{"de":"Eigene Einladungsseite in drei Minuten: Countdown, Google-Maps-Route, WhatsApp-Versand und Zusagen. Für Hochzeitspaare von Han Studio kostenlos.","tr":"Üç dakikada kendi davetiye sayfanız: geri sayım, Google Maps yol tarifi, WhatsApp paylaşımı ve katılım bildirimi. Han Studio çiftlerine ücretsiz.","en":"Your own invitation page in three minutes: countdown, Google Maps route, WhatsApp sharing and replies. Free for wedding couples of Han Studio."}},"impressum":{"image":"","title":{"de":"","tr":""},"noindex":false,"description":{"de":"","tr":""}},"portfolio":{"image":"","title":{"de":"Portfolio – echte Hochzeiten aus Stuttgart & Region","tr":"Portfolyo – Stuttgart ve bölgeden gerçek düğünler","en":"Portfolio – real weddings from Stuttgart & the region"},"noindex":false,"description":{"de":"Vier Hochzeitsreportagen aus Stuttgart, Ludwigsburg und Fellbach – Schloss, Kelter und große Eventhalle.","tr":"Stuttgart, Ludwigsburg ve Fellbach\'tan dört düğün çekimi – saray, şaraphane ve büyük etkinlik salonu.","en":"Four wedding stories from Stuttgart, Ludwigsburg and Fellbach – a palace, a wine press house and a large event hall."}},"leistungen":{"image":"","title":{"de":"Leistungen – Hochzeitsfotografie & Hochzeitsfilm","tr":"Hizmetler – düğün fotoğrafçılığı & düğün filmi","en":"Services – wedding photography & wedding film"},"noindex":false,"description":{"de":"Hochzeitsreportage, Hochzeitsfilm in 4K, Standesamt, Henna-Abend und After-Wedding-Shooting in Krumbach und Bayerisch-Schwaben.","tr":"Stuttgart ve çevresinde düğün çekimi, 4K düğün filmi, nikah, kına gecesi ve after-wedding çekimi.","en":"Wedding reportage, wedding film in 4K, registry office, henna night and after-wedding shoot in Krumbach and Bavarian Swabia."}},"ueber-mich":{"image":"","title":{"de":"","tr":""},"noindex":false,"description":{"de":"","tr":""}},"datenschutz":{"image":"","title":{"de":"","tr":""},"noindex":false,"description":{"de":"","tr":""}},"hochzeitslocations":{"image":"","title":{"de":"Hochzeitslocations Stuttgart & Region – Fotograf mit Ortskenntnis","tr":"Stuttgart ve çevresi düğün mekânları – mekânı tanıyan fotoğrafçı","en":"Wedding venues Stuttgart & region – a photographer who knows them"},"noindex":false,"description":{"de":"Schloss, Festhalle, Eventlocation: Für die beliebtesten Hochzeitslocations der Region Stuttgart kennen wir Licht, Zeitplan und Hausregeln.","tr":"Saray, düğün salonu, etkinlik mekânı: Stuttgart bölgesinin en çok tercih edilen düğün mekânlarında ışığı, zaman planını ve kuralları biliyoruz.","en":"Palace, festival hall, event venue: for the most popular wedding venues in the Stuttgart region we know the light, the timeline and the house rules."}}},"templates":{"city":{"de":"Hochzeitsfotograf {name} – Foto & Video ab 690 €","tr":"{name} Düğün Fotoğrafçısı – Foto & Video 690 €\'dan","en":"Wedding photographer {name} – photo & video from 690 €"},"post":{"de":"{title}","tr":"{title}","en":"{title}"},"story":{"de":"{couple} – {venue}","tr":"{couple} – {venue}","en":"{couple} – {venue}"},"venue":{"de":"{name} Hochzeitsfotograf – Erfahrung vor Ort","tr":"{name} düğün fotoğrafçısı – mekân tecrübesi","en":"{name} wedding photographer – we know the place"}},"defaultImage":""},"testimonials":[{"city":{"de":"Stuttgart","tr":"Stuttgart","en":"Stuttgart"},"name":"Elif & Marco","text":{"de":"Wir haben euch den ganzen Tag kaum bemerkt – und dann waren da 600 Bilder, auf denen alles drauf ist, was uns wichtig war.","tr":"Gün boyu sizi neredeyse fark etmedik – sonra bizim için önemli olan her şeyin olduğu 600 kare çıktı.","en":"We barely noticed you all day – and then there were 600 pictures with everything on them that mattered to us."}},{"city":{"de":"Fellbach","tr":"Fellbach","en":"Fellbach"},"name":"Sarah & Daniel","text":{"de":"Die Online-Galerie war für unsere Familien perfekt. Meine Mutter in Izmir hat die Bilder am selben Abend gesehen.","tr":"Online galeri ailelerimiz için mükemmeldi. Annem İzmir\'de kareleri aynı akşam gördü.","en":"The online gallery was perfect for our families. My mother in Izmir saw the pictures the same evening."}},{"city":{"de":"Ludwigsburg","tr":"Ludwigsburg","en":"Ludwigsburg"},"name":"Aylin & Emre","text":{"de":"Der Film hat meinen Vater zum Weinen gebracht. Mehr muss man dazu nicht sagen.","tr":"Film babamı ağlattı. Daha fazla söze gerek yok.","en":"The film made my father cry. There is nothing more to say about it."}}],"texts":{"home.heroEyebrow":{"de":"Hochzeitsfotografie & Film · Krumbach & Bayerisch-Schwaben","tr":"Düğün fotoğrafçılığı & film · Krumbach ve Bavyera-Suabya","en":"Wedding photography & film · Krumbach & Bavarian Swabia"},"home.heroText":{"de":"Dokumentarische Hochzeitsfotografie und Film in Krumbach, zwischen Ulm, Augsburg und dem Allgäu. Ruhig gearbeitet, ehrlich erzählt – und pünktlich geliefert.","tr":"Krumbach’ta, Ulm ile Augsburg ve Allgäu arasında belgesel tarzda düğün fotoğrafçılığı ve video. Sakin çalışılmış, dürüst anlatılmış – ve zamanında teslim edilmiş.","en":"Documentary wedding photography and film in Krumbach, between Ulm, Augsburg and the Allgäu. Worked quietly, told honestly – and delivered on time."},"home.citiesText":{"de":"Krumbach und 80 km Umkreis ohne Anfahrtskosten – von Günzburg und Ulm bis Augsburg und Memmingen. Für jede Stadt kennen wir Trauorte, Licht und Wege.","tr":"Krumbach ve 80 km çevresi yol ücretsiz – Günzburg ve Ulm’dan Augsburg ve Memmingen’e. Her şehir için nikâh yerlerini, ışığı ve yolları biliyoruz.","en":"Krumbach and 80 km around it with no travel costs – from Günzburg and Ulm to Augsburg and Memmingen. For every town we know the ceremony venues, the light and the roads."},"footer.tagline":{"de":"Hochzeitsfotografie & Film in Krumbach und Bayerisch-Schwaben.","tr":"Krum